"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { BrowserMultiFormatReader } from "@zxing/browser";
import { supabaseBrowser } from "@/lib/supabase/client";
import { useTenantEmpresa } from "@/lib/auth/useTenantEmpresa";

type ItemRow = {
  id: string;
  codigo: string;
  descricao: string;
  quantidade: number | null;
  quantidadeText: string;
  itemId: number | null;
  tipo: string | null;
  finalidade: string | null;
  controlaEstoque: boolean | null;
  valorUnitario: number | null;
  estoqueAtual: number | null;
  itemFound?: boolean | null;
  itemLoading?: boolean;
  itemError?: string | null;
};

type OsInfo = {
  id: number;
  descricao: string;
  status: string | null;
  clienteNome: string;
};

type CachedItem = {
  id: number;
  descricao: string;
  tipo: string | null;
  finalidade: string | null;
  controlaEstoque: boolean | null;
  valorUnitario: number | null;
  estoqueAtual: number | null;
};

type ClienteRow = {
  nome: string | null;
  razao_social: string | null;
};

type OsRow = {
  id: number;
  numero_os?: string | null;
  descricao_servico?: string | null;
  descricao?: string | null;
  status?: string | null;
  cliente_nome?: string | null;
  cliente_id?: number | null;
};

type ItemLookupRow = {
  id: number;
  codigo_interno?: string | null;
  nome?: string | null;
  descricao?: string | null;
  tipo?: string | null;
  finalidade?: string | null;
  controla_estoque?: boolean | null;
  preco_unitario?: number | null;
};

type EstoqueQuantidadeRow = {
  quantidade_atual: number | null;
};

type EstoqueItemRow = {
  item_id: number;
  quantidade_atual: number | null;
};

type DetectorLike = {
  detect: (source: HTMLVideoElement) => Promise<Array<{ rawValue?: string }>>;
};

type ZxingControls = {
  stop: () => void;
};

const createEmptyRow = (): ItemRow => ({
  id: typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : Math.random().toString(36).slice(2, 8),
  codigo: "",
  descricao: "",
  quantidade: null,
  quantidadeText: "",
  itemId: null,
  tipo: null,
  finalidade: null,
  controlaEstoque: null,
  valorUnitario: null,
  estoqueAtual: null,
  itemFound: null,
  itemLoading: false,
  itemError: null,
});

const isRowEmpty = (row: ItemRow) =>
  row.codigo.trim() === "" && row.descricao.trim() === "" && row.quantidadeText.trim() === "";

const isRowComplete = (row: ItemRow) => {
  const qtyValid = row.quantidade !== null && !Number.isNaN(row.quantidade);
  const hasFound = row.itemFound === true;
  const hasId = row.itemId !== null;
  return hasFound && qtyValid && hasId;
};

function ensureTrailingEmptyRow(rows: ItemRow[]) {
  const next = rows.length ? [...rows] : [createEmptyRow()];

  while (next.length > 1 && isRowEmpty(next[next.length - 1]) && isRowEmpty(next[next.length - 2])) {
    next.pop();
  }

  const last = next[next.length - 1];
  if (isRowComplete(last)) {
    next.push(createEmptyRow());
  }

  return next;
}

const statusLabels: Record<string, { label: string; className: string }> = {
  em_andamento: { label: "Em andamento", className: "bg-emerald-900/50 text-emerald-100" },
  aberta: { label: "Aberta", className: "bg-zinc-800 text-zinc-200" },
  concluida: { label: "Concluida", className: "bg-blue-900/50 text-blue-100" },
  cancelada: { label: "Cancelada", className: "bg-red-900/50 text-red-100" },
};

function getErrorMessage(err: unknown, fallback: string) {
  if (err instanceof Error) return err.message;
  if (typeof err === "string") return err;
  if (err && typeof err === "object" && "message" in err) {
    const msg = (err as { message?: string }).message;
    if (typeof msg === "string" && msg.trim() !== "") return msg;
  }
  return fallback;
}

export default function BaixaOsCelPage() {
  const supabase = useMemo(() => {
    if (typeof window === "undefined") return null as unknown as ReturnType<typeof supabaseBrowser>;
    return supabaseBrowser();
  }, []);
  const { tenantId, empresaId } = useTenantEmpresa();
  const fixedTenantId = "3ced7cfa-efbb-4f0f-addc-2028f60d1ca7";
  const fixedEmpresaId = "f0e74f49-a127-46b4-901b-f7b37e43c690";
  const effectiveTenantId = useMemo(() => tenantId ?? fixedTenantId, [tenantId]);
  const effectiveEmpresaId = useMemo(() => empresaId ?? fixedEmpresaId, [empresaId]);
  const [tenantValidated, setTenantValidated] = useState(false);

  const [os, setOs] = useState("");
  const [osDescricao, setOsDescricao] = useState("");
  const [osId, setOsId] = useState<number | null>(null);
  const [osStatus, setOsStatus] = useState<string | null>(null);
  const [osClienteNome, setOsClienteNome] = useState("");
  const [osLoading, setOsLoading] = useState(false);
  const [osError, setOsError] = useState<string | null>(null);

  const [showOsLookup, setShowOsLookup] = useState(false);
  const [osLookupTerm, setOsLookupTerm] = useState("");
  const [osLookupRows, setOsLookupRows] = useState<OsRow[]>([]);
  const [osLookupLoading, setOsLookupLoading] = useState(false);
  const [osLookupError, setOsLookupError] = useState<string | null>(null);

  const [rows, setRows] = useState<ItemRow[]>([createEmptyRow()]);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [supportsDetector, setSupportsDetector] = useState(false);
  const [supportsCamera, setSupportsCamera] = useState(false);
  const [scanMode, setScanMode] = useState<"detector" | "zxing" | "none">("none");
  const [scanningRowId, setScanningRowId] = useState<string | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [ocrBusyRowId, setOcrBusyRowId] = useState<string | null>(null);

  const validItems = useMemo(() => rows.filter(isRowComplete), [rows]);

  const osCacheRef = useRef<Record<string, OsInfo | null>>({});
  const itemCacheRef = useRef<Record<string, CachedItem | null>>({});
  const osDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const osLookupDebounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const itemDebounceRef = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const scanLoopRef = useRef<number | null>(null);
  const detectorRef = useRef<DetectorLike | null>(null);
  const zxingReaderRef = useRef<BrowserMultiFormatReader | null>(null);
  const zxingControlsRef = useRef<ZxingControls | null>(null);
  const ocrInputRef = useRef<HTMLInputElement | null>(null);
  const ocrRowRef = useRef<string | null>(null);

  useEffect(() => {
    setTenantValidated(true);
  }, [tenantId, effectiveTenantId]);

  useEffect(() => {
    const hasDetector = typeof window !== "undefined" && "BarcodeDetector" in window;
    const hasCamera = typeof navigator !== "undefined" && !!navigator.mediaDevices?.getUserMedia;
    setSupportsDetector(hasDetector);
    setSupportsCamera(hasCamera);
    setScanMode(hasDetector ? "detector" : hasCamera ? "zxing" : "none");
  }, []);

  useEffect(() => {
    const timeoutsRef = itemDebounceRef.current;
    return () => {
      if (osDebounceRef.current) clearTimeout(osDebounceRef.current);
      if (osLookupDebounceRef.current) clearTimeout(osLookupDebounceRef.current);
      const timeouts = Object.values(timeoutsRef);
      timeouts.forEach((t) => clearTimeout(t));
      stopScan();
    };
  }, []);

  const normalizeOsNumber = (numero: string) => {
    const trimmed = numero.trim();
    if (/^\d+$/.test(trimmed)) {
      return String(Number(trimmed));
    }
    return trimmed;
  };

  const fetchClienteNome = useCallback(async (clienteId: number | null, clienteNomeInline: string | null) => {
    if (clienteNomeInline && clienteNomeInline.trim() !== "") {
      return clienteNomeInline.trim();
    }
    if (!clienteId) return "-";

    const { data, error: cliErr } = await supabase
      .from("clientes")
      .select("nome,razao_social")
      .eq("id", clienteId)
      .maybeSingle();

    if (cliErr || !data) return "-";
    const cliente = data as ClienteRow;
    const nome = cliente.nome ?? cliente.razao_social ?? "";
    return nome.trim() === "" ? "-" : nome;
  }, [supabase]);

  const fetchOs = useCallback(async (numero: string) => {
    const normalized = normalizeOsNumber(numero);
    if (!normalized) {
      setOsDescricao("");
      setOsId(null);
      setOsStatus(null);
      setOsClienteNome("");
      setOsError(null);
      return;
    }

    if (osCacheRef.current[normalized] !== undefined) {
      const cached = osCacheRef.current[normalized];
      if (cached) {
        setOsDescricao(cached.descricao);
        setOsId(cached.id);
        setOsStatus(cached.status);
        setOsClienteNome(cached.clienteNome);
        setOsError(null);
      } else {
        setOsDescricao("");
        setOsId(null);
        setOsStatus(null);
        setOsClienteNome("");
        setOsError("OS nao encontrada");
      }
      return;
    }

    setOsLoading(true);
    setOsError(null);

    const { data, error: queryError } = await supabase
      .from("ordens_servico")
      .select("id,descricao_servico,status,cliente_nome,cliente_id")
      .eq("numero_os", normalized)
      .maybeSingle();

    setOsLoading(false);

    if (queryError) {
      setOsDescricao("");
      setOsId(null);
      setOsStatus(null);
      setOsClienteNome("");
      setOsError("Erro ao buscar OS");
      osCacheRef.current[normalized] = null;
      return;
    }

    if (!data) {
      setOsDescricao("");
      setOsId(null);
      setOsStatus(null);
      setOsClienteNome("");
      setOsError("OS nao encontrada");
      osCacheRef.current[normalized] = null;
      return;
    }

    const osRow = data as OsRow;
    const osIdDb = Number(osRow.id ?? null);
    const descricaoDb = osRow.descricao_servico ?? osRow.descricao ?? "";
    const statusDb = osRow.status ?? null;
    const clienteNomeInline = osRow.cliente_nome ?? null;
    const clienteId = osRow.cliente_id ?? null;

    const clienteNome = await fetchClienteNome(clienteId, clienteNomeInline);

    osCacheRef.current[normalized] = { id: osIdDb, descricao: descricaoDb, status: statusDb, clienteNome };
    setOsDescricao(descricaoDb);
    setOsId(osIdDb);
    setOsStatus(statusDb);
    setOsClienteNome(clienteNome);
    setOsError(null);
  }, [fetchClienteNome, supabase]);

  const openOsLookup = () => {
    setOsLookupTerm("");
    setOsLookupRows([]);
    setOsLookupError(null);
    setShowOsLookup(true);
  };

  const closeOsLookup = () => {
    setShowOsLookup(false);
  };

  const loadOsLookup = useCallback(async (term: string) => {
    setOsLookupLoading(true);
    setOsLookupError(null);

    const trimmed = term.trim();
    if (!trimmed) {
      setOsLookupRows([]);
      setOsLookupLoading(false);
      return;
    }

    let query = supabase
      .from("ordens_servico")
      .select("id,numero_os,cliente_nome,descricao_servico,status")
      .order("id", { ascending: false })
      .limit(50)
      .eq("status", "em_andamento");

    if (trimmed) {
      query = query.or(`numero_os.ilike.%${trimmed}%,cliente_nome.ilike.%${trimmed}%`);
    }

    const { data, error: queryError } = await query;

    setOsLookupLoading(false);

    if (queryError) {
      setOsLookupError("Erro ao buscar OS");
      setOsLookupRows([]);
      return;
    }

    setOsLookupRows((data ?? []) as OsRow[]);
  }, [supabase]);

  const fetchItem = async (rowId: string, codigo: string) => {
    const trimmed = codigo.trim();
    if (!trimmed) {
      setRows((prev) =>
        prev.map((r) =>
          r.id === rowId
            ? {
                ...r,
                descricao: "",
                itemId: null,
                tipo: null,
                finalidade: null,
                controlaEstoque: null,
                valorUnitario: null,
                estoqueAtual: null,
                itemFound: null,
                itemError: null,
                itemLoading: false,
              }
            : r
        )
      );
      return;
    }

    const isNumeric = /^\d+$/.test(trimmed);
    const cacheKey = isNumeric ? String(Number(trimmed)) : trimmed;
    const queryValue = isNumeric ? Number(cacheKey) : trimmed;

    if (itemCacheRef.current[cacheKey] !== undefined) {
      const cached = itemCacheRef.current[cacheKey];
      if (cached) {
        setRows((prev) =>
          ensureTrailingEmptyRow(
            prev.map((r) =>
              r.id === rowId
                ? {
                    ...r,
                    descricao: cached?.descricao ?? "",
                    itemId: cached?.id ?? null,
                    tipo: cached?.tipo ?? null,
                    finalidade: cached?.finalidade ?? null,
                    controlaEstoque: cached?.controlaEstoque ?? null,
                    valorUnitario: cached?.valorUnitario ?? null,
                    estoqueAtual: cached?.estoqueAtual ?? null,
                    itemFound: cached !== null,
                    itemError:
                      cached && (cached.finalidade ?? "") !== "materia_prima"
                        ? "Apenas materia-prima"
                        : cached
                          ? null
                          : "Item nao encontrado",
                    itemLoading: false,
                  }
                : r
            )
          )
        );
        return;
      }
    }

    setRows((prev) =>
      prev.map((r) => (r.id === rowId ? { ...r, itemLoading: true, itemError: null } : r))
    );

    let data: ItemLookupRow | null = null;
    let queryError: { message?: string } | null = null;

    const selectFields = "id,codigo_interno,nome,descricao,tipo,finalidade,controla_estoque,preco_unitario";

    if (isNumeric) {
      const byNumber = await supabase.from("itens").select(selectFields).eq("id", queryValue).maybeSingle();
      data = (byNumber.data ?? null) as ItemLookupRow | null;
      queryError = byNumber.error ?? null;
      if (!data && !queryError) {
        const byString = await supabase.from("itens").select(selectFields).eq("id", cacheKey).maybeSingle();
        data = (byString.data ?? null) as ItemLookupRow | null;
        queryError = byString.error ?? null;
      }
    } else {
      const byString = await supabase.from("itens").select(selectFields).eq("id", queryValue).maybeSingle();
      data = (byString.data ?? null) as ItemLookupRow | null;
      queryError = byString.error ?? null;
    }

    if (queryError) {
      setRows((prev) =>
        prev.map((r) =>
          r.id === rowId
            ? {
                ...r,
                descricao: "",
                itemId: null,
                tipo: null,
                finalidade: null,
                controlaEstoque: null,
                valorUnitario: null,
                itemFound: false,
                itemError: "Erro ao buscar item",
                itemLoading: false,
              }
            : r
        )
      );
      itemCacheRef.current[cacheKey] = null;
      return;
    }

    if (!data) {
      setRows((prev) =>
        prev.map((r) =>
          r.id === rowId
            ? {
                ...r,
                descricao: "",
                itemId: null,
                tipo: null,
                finalidade: null,
                controlaEstoque: null,
                valorUnitario: null,
                itemFound: false,
                itemError: "Item nao encontrado",
                itemLoading: false,
              }
            : r
        )
      );
      itemCacheRef.current[cacheKey] = null;
      return;
    }

    const codigoInterno = data.codigo_interno ?? "";
    const nomeDesc = data.nome ?? data.descricao ?? "";
    const desc = codigoInterno ? `[${codigoInterno}] ${nomeDesc}` : nomeDesc;
    const tipo = data.tipo ?? null;
    const finalidade = data.finalidade ?? null;
    const controlaEstoque = data.controla_estoque ?? null;
    const valorUnitarioRaw = Number(data.preco_unitario ?? null);
    const valorUnitario = Number.isFinite(valorUnitarioRaw) ? valorUnitarioRaw : null;
    const itemId = Number(data.id);

    let estoqueAtual: number | null = null;
    const { data: estoqueData } = await supabase
      .from("estoque")
      .select("quantidade_atual")
      .eq("item_id", itemId)
      .maybeSingle();
    const estoqueRow = (estoqueData ?? null) as EstoqueQuantidadeRow | null;
    if (estoqueRow) estoqueAtual = Number(estoqueRow.quantidade_atual ?? 0);

    const isMateriaPrima = (finalidade ?? "") === "materia_prima";
    const itemError = isMateriaPrima ? null : "Apenas materia-prima";

    itemCacheRef.current[cacheKey] = {
      id: itemId,
      descricao: desc,
      tipo,
      finalidade,
      controlaEstoque,
      valorUnitario,
      estoqueAtual,
    };

    setRows((prev) =>
      ensureTrailingEmptyRow(
        prev.map((r) =>
          r.id === rowId
            ? {
                ...r,
                descricao: desc,
                itemId,
                tipo,
                finalidade,
                controlaEstoque,
                valorUnitario,
                estoqueAtual,
                itemFound: true,
                itemError,
                itemLoading: false,
              }
            : r
        )
      )
    );
  };

  const handleRowChange = (id: string, field: "codigo" | "descricao" | "quantidade", value: string) => {
    setRows((prev) => {
      const updated = prev.map((row) => {
        if (row.id !== id) return row;

        if (field === "quantidade") {
          const normalized = value.replace(",", ".").trim();
          const parsed = normalized === "" ? null : Number(normalized);
          return {
            ...row,
            quantidadeText: value,
            quantidade: Number.isNaN(parsed) ? null : parsed,
          };
        }

        if (field === "codigo") {
          return {
            ...row,
            codigo: value,
            itemFound: null,
            itemError: null,
            itemId: null,
            tipo: null,
            finalidade: null,
            controlaEstoque: null,
            valorUnitario: null,
            estoqueAtual: null,
          };
        }

        return row;
      });

      return ensureTrailingEmptyRow(updated);
    });

    if (field === "codigo") {
      if (itemDebounceRef.current[id]) clearTimeout(itemDebounceRef.current[id]);
      itemDebounceRef.current[id] = setTimeout(() => {
        fetchItem(id, value);
      }, 250);
    }
  };

  const removeRow = (id: string) => {
    setRows((prev) => {
      const idx = prev.findIndex((r) => r.id === id);
      if (idx === -1) return prev;
      if (idx === prev.length - 1 && isRowEmpty(prev[idx])) return prev;

      const next = prev.filter((r) => r.id !== id);
      return ensureTrailingEmptyRow(next.length ? next : [createEmptyRow()]);
    });
  };

  const handleScannedCode = (rowId: string, code: string) => {
    const clean = code?.trim();
    if (!clean) return;
    setRows((prev) =>
      ensureTrailingEmptyRow(
        prev.map((r) => (r.id === rowId ? { ...r, codigo: clean, itemFound: null, itemError: null } : r))
      )
    );
    fetchItem(rowId, clean);
  };

  const triggerOcrCapture = (rowId: string) => {
    ocrRowRef.current = rowId;
    if (ocrInputRef.current) {
      ocrInputRef.current.value = "";
      ocrInputRef.current.click();
    }
  };

  const handleOcrFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const rowId = ocrRowRef.current;
    if (!file || !rowId) return;

    setScanError(null);
    setOcrBusyRowId(rowId);

    try {
      const { default: Tesseract } = await import("tesseract.js");
      const { data } = await Tesseract.recognize(file, "eng");
      const raw = (data?.text ?? "").replace(/\s+/g, " ").trim();
      const normalized = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      const codMatch = normalized.match(/cod(?:igo)?\.?\s*[:\-]?\s*([0-9]{2,})/i);
      const codNumber = codMatch?.[1] ?? "";
      const numericMatches = raw.match(/\d{2,}/g) || [];
      const bestNumeric = numericMatches.sort((a, b) => b.length - a.length)[0];
      const fallbackMatch = raw.match(/[0-9A-Za-z_.-]+/);
      const code = codNumber || bestNumeric || fallbackMatch?.[0] || "";
      if (code) {
        handleScannedCode(rowId, code);
      } else {
        setScanError("Nada reconhecido na foto. Tente enquadrar apenas o numero.");
      }
    } catch (err: unknown) {
      setScanError(getErrorMessage(err, "Erro ao processar OCR."));
    } finally {
      setOcrBusyRowId(null);
      ocrRowRef.current = null;
      if (ocrInputRef.current) ocrInputRef.current.value = "";
    }
  };

  const stopScan = () => {
    if (scanLoopRef.current) {
      cancelAnimationFrame(scanLoopRef.current);
      scanLoopRef.current = null;
    }
    if (zxingControlsRef.current) {
      try {
        zxingControlsRef.current.stop();
      } catch {
        // noop
      }
      zxingControlsRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    setScanningRowId(null);
  };

  const startScan = async (rowId: string) => {
    setScanError(null);
    if (!supportsCamera) {
      setScanError("Camera indisponivel neste dispositivo.");
      return;
    }
    const willUseDetector = supportsDetector;
    try {
      if (willUseDetector) {
        const detectorCtor = (window as unknown as { BarcodeDetector?: new (options: { formats?: string[] }) => DetectorLike })
          .BarcodeDetector;
        if (!detectorRef.current) {
          if (detectorCtor) {
            detectorRef.current = new detectorCtor({
              formats: ["code_128", "code_39", "ean_13", "ean_8", "qr_code", "codabar"],
            });
          }
        }

        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: { ideal: "environment" },
            width: { ideal: 1280 },
            height: { ideal: 720 },
          },
        });

        streamRef.current = stream;
        setScanningRowId(rowId);
        setScanMode("detector");

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }

        const detect = async () => {
          if (!detectorRef.current || !videoRef.current) return;
          try {
            const codes = await detectorRef.current.detect(videoRef.current);
            if (codes?.length) {
              const codeText = codes[0]?.rawValue ?? "";
              if (codeText) {
                handleScannedCode(rowId, codeText);
                stopScan();
                return;
              }
            }
          } catch (err: unknown) {
            setScanError(getErrorMessage(err, "Erro ao ler codigo."));
          }
          scanLoopRef.current = requestAnimationFrame(detect);
        };

        detect();
      } else {
        // ZXing fallback (melhor suporte no iOS)
        if (!zxingReaderRef.current) {
          zxingReaderRef.current = new BrowserMultiFormatReader();
        }
        const reader = zxingReaderRef.current;
        const controls = await reader.decodeFromVideoDevice(
          undefined,
          videoRef.current!,
          (result, err) => {
            if (result && result.getText()) {
              handleScannedCode(rowId, result.getText());
              stopScan();
            }
            if (err && err.name !== "NotFoundException") {
              setScanError(err.message);
            }
          }
        );
        zxingControlsRef.current = controls;
        setScanningRowId(rowId);
        setScanMode("zxing");
      }
    } catch (err: unknown) {
      setScanError(getErrorMessage(err, "Nao foi possivel abrir a camera."));
      stopScan();
    }
  };

  const handleSubmit = async () => {
    const messages: string[] = [];
    setSuccess(null);

    if (os.trim() === "") messages.push("Informe a OS");
    if (osStatus !== "em_andamento") messages.push("So e possivel baixar itens em OS em andamento.");
    if (!osId) messages.push("OS nao encontrada");
    if (!empresaId) messages.push("Selecione uma empresa antes de baixar itens.");

    const hasInvalidQty = rows.some((r) => r.quantidade === null && r.quantidadeText.trim() !== "");
    if (hasInvalidQty) messages.push("Quantidade invalida");

    const hasMissingCode = rows.some((r, idx) => {
      const isLastEmpty = idx === rows.length - 1 && isRowEmpty(r);
      if (isLastEmpty) return false;
      const hasCode = r.codigo.trim() !== "";
      const hasQty = r.quantidadeText.trim() !== "" || r.quantidade !== null;
      return hasCode && hasQty && r.itemFound !== true;
    });
    if (hasMissingCode) messages.push("Item nao encontrado");

    const hasMissingId = rows.some((r) => r.itemFound === true && r.itemId === null);
    if (hasMissingId) messages.push("Item invalido");
    const hasNonMateriaPrima = rows.some(
      (r) => r.itemFound === true && (r.finalidade ?? "") !== "materia_prima"
    );
    if (hasNonMateriaPrima) messages.push("Apenas itens de materia-prima podem ser baixados");

    if (validItems.length === 0) messages.push("Informe pelo menos 1 item");

    if (messages.length) {
      setError(messages[0]);
      return;
    }

    setError(null);

    const itemIds = validItems.map((r) => r.itemId).filter((id): id is number => id !== null);
    const estoqueMap = new Map<number, number>();
    if (itemIds.length > 0) {
      const { data: estoqueData, error: estoqueErr } = await supabase
        .from("estoque")
        .select("item_id,quantidade_atual")
        .in("item_id", itemIds);

      if (estoqueErr) {
        setError("Erro ao consultar estoque");
        return;
      }

      const estoqueRows = (estoqueData ?? []) as EstoqueItemRow[];
      estoqueRows.forEach((e) => {
        estoqueMap.set(Number(e.item_id), Number(e.quantidade_atual ?? 0));
      });
    }

    const insuficiente = validItems.find((r) => {
      const precisaBaixa = (r.finalidade ?? "") === "materia_prima" && r.controlaEstoque !== false;
      if (!precisaBaixa || r.itemId === null) return false;
      const saldo = estoqueMap.has(r.itemId) ? estoqueMap.get(r.itemId)! : 0;
      return Number(r.quantidade ?? 0) > saldo;
    });

    if (insuficiente) {
      const saldo =
        insuficiente.itemId !== null && estoqueMap.has(insuficiente.itemId)
          ? estoqueMap.get(insuficiente.itemId)!
          : 0;
      setError(
        `Sem saldo suficiente para o item ${insuficiente.codigo || insuficiente.descricao}. Saldo atual: ${saldo.toLocaleString(
          "pt-BR"
        )}`
      );
      return;
    }

    setSubmitting(true);

    const { data: sess } = await supabase.auth.getSession();
    const userEmail = sess.session?.user?.email ?? null;

    for (const item of validItems) {
      const precisaBaixa = (item.finalidade ?? "") === "materia_prima" && item.controlaEstoque !== false;
      const { error: rpcErr } = await supabase.rpc("add_os_item_baixa_imediata", {
        p_os_id: osId,
        p_item_id: item.itemId,
        p_quantidade: item.quantidade as number,
        p_valor_unitario: Number(item.valorUnitario ?? 0),
        p_baixa_estoque: precisaBaixa,
        p_realizado_por: userEmail,
        p_motivo: "Baixa manual pela tela Baixa OS Cel",
        p_empresa_id: empresaId,
      });

      if (rpcErr) {
        setSubmitting(false);
        setError(rpcErr.message);
        return;
      }
    }

    setSubmitting(false);
    setSuccess("Itens baixados e registrados na OS.");
    setRows([createEmptyRow()]);
  };

  useEffect(() => {
    if (osDebounceRef.current) clearTimeout(osDebounceRef.current);
    osDebounceRef.current = setTimeout(() => {
      fetchOs(os);
    }, 300);

    return () => {
      if (osDebounceRef.current) clearTimeout(osDebounceRef.current);
    };
  }, [os, fetchOs]);

  const canSubmit = osStatus === "em_andamento" && !!osDescricao && osId !== null;
  const submitEnabled = canSubmit && !submitting;

  const statusDisplay = osStatus ? statusLabels[osStatus]?.label ?? "-" : "-";
  const statusClass =
    osStatus && statusLabels[osStatus] ? statusLabels[osStatus].className : "bg-zinc-800 text-zinc-200";
  const scanStatusLabel =
    scanMode === "detector"
      ? "Camera pronta (nativo)"
      : scanMode === "zxing"
        ? "Camera pronta (ZXing)"
        : "Camera indisponivel";
  const scanStatusClass =
    scanMode === "none" ? "text-amber-300" : scanMode === "detector" ? "text-emerald-300" : "text-blue-200";

  return (
    <div className="min-h-screen px-3 py-4 bg-zinc-950">
      <div className="mx-auto max-w-xl space-y-4">
        <header className="space-y-1">
          <p className="text-xs uppercase tracking-[0.12em] text-blue-300/80">Apontamento celular</p>
          <h1 className="text-2xl font-semibold text-zinc-100">Baixa OS (Cel)</h1>
          <p className="text-sm text-zinc-400">
            Focado em celular: digite, leia por camera (codigo de barras/QR) ou foto OCR de numeros e informe a quantidade.
          </p>
        </header>

        <div className="space-y-3 rounded-2xl border border-zinc-800 bg-zinc-900/70 p-4 shadow">
          <div className="grid grid-cols-1 gap-3">
            <div className="grid grid-cols-[1fr_1fr] gap-3">
              <label className="flex flex-col gap-1 text-sm font-medium text-zinc-200">
                <span>OS</span>
                <div className="flex gap-2 items-end">
                  <div className="relative flex-1">
                    <input
                      value={os}
                      onChange={(e) => setOs(e.target.value)}
                      disabled={!tenantValidated}
                      onKeyDown={(e) => {
                        if (e.key === "Enter" && os.trim() === "") {
                          e.preventDefault();
                          openOsLookup();
                        }
                      }}
                      enterKeyHint="next"
                      className="w-full rounded-lg border border-zinc-800 bg-zinc-950 px-3 py-3 text-lg text-white placeholder:text-zinc-500 focus:border-blue-500 focus:outline-none"
                      placeholder="Numero da OS"
                      autoComplete="off"
                      inputMode="numeric"
                    />
                    {osLoading && (
                      <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[11px] text-blue-300">
                        carregando...
                      </span>
                    )}
                  </div>
                  <button
                    type="button"
                    onClick={openOsLookup}
                    className="shrink-0 px-4 py-3 rounded-xl border border-zinc-700 bg-zinc-900 text-sm text-zinc-100 hover:bg-zinc-800"
                  >
                    Pesquisar
                  </button>
                </div>
                {osError && <span className="text-xs text-red-300">{osError}</span>}
              </label>

              <label className="flex flex-col gap-1 text-sm font-medium text-zinc-200">
                <span>Cliente</span>
                <input
                  value={osClienteNome || "-"}
                  readOnly
                  title="Campo preenchido automaticamente"
                  className="w-full rounded-lg border border-zinc-800 bg-zinc-900 px-3 py-3 text-lg text-white placeholder:text-zinc-500 focus:border-blue-500 focus:outline-none opacity-90 cursor-not-allowed"
                />
              </label>
            </div>
          </div>

          <label className="flex flex-col gap-1 text-sm font-medium text-zinc-200">
            <span>Descricao</span>
            <textarea
              value={osDescricao}
              readOnly
              title="Campo preenchido automaticamente"
              className="w-full rounded-lg border border-zinc-800 bg-zinc-900 px-3 py-3 text-lg text-white placeholder:text-zinc-500 focus:border-blue-500 focus:outline-none min-h-[80px] opacity-90 cursor-not-allowed"
              placeholder="Descricao da OS"
            />
          </label>

          <div className="flex flex-col gap-1 text-sm font-medium text-zinc-200">
            <span>Condicao</span>
            <div className={`rounded-lg border border-zinc-800 px-3 py-3 text-lg ${statusClass}`}>
              {statusDisplay}
            </div>
          </div>
        </div>

        <div className="space-y-3 rounded-2xl border border-zinc-800 bg-zinc-900/70 p-4 shadow">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-lg font-semibold text-zinc-100">Itens</h2>
              <p className="text-xs text-zinc-500">Use camera ou digitacao rapida.</p>
            </div>
            <span className={`text-[11px] ${scanStatusClass}`}>{scanStatusLabel}</span>
          </div>

          <div className="space-y-2">
            {rows.map((row, idx) => {
              const showRemove = !(idx === rows.length - 1 && isRowEmpty(row));

              return (
                <div key={row.id} className="space-y-2 rounded-xl border border-zinc-800 bg-zinc-950 p-3 shadow-sm">
                  <div className="flex gap-2">
                    <div className="flex-1">
                      <div className="text-[11px] uppercase text-zinc-400">Codigo</div>
                      <div className="flex gap-2 items-center">
                        <div className="relative flex-1">
                          <input
                            value={row.codigo}
                            onChange={(e) => handleRowChange(row.id, "codigo", e.target.value)}
                            className="w-full rounded-lg bg-zinc-900 px-3 py-3 text-base text-white placeholder:text-zinc-500 focus:border focus:border-blue-500 focus:outline-none border border-zinc-800/70"
                            placeholder="ID ou codigo do item"
                            autoComplete="off"
                            enterKeyHint="next"
                            inputMode="text"
                          />
                          {row.itemLoading && (
                            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[11px] text-blue-300">
                              ...
                            </span>
                          )}
                        </div>
                        <button
                          type="button"
                          onClick={() => (scanningRowId === row.id ? stopScan() : startScan(row.id))}
                          className={`shrink-0 rounded-lg px-3 py-2 text-sm font-semibold ${
                            scanningRowId === row.id
                              ? "border border-emerald-500/60 bg-emerald-900/40 text-emerald-100"
                              : "border border-blue-500/50 bg-blue-500/10 text-blue-100 hover:bg-blue-500/20"
                          }`}
                          disabled={!supportsCamera}
                        >
                          {scanningRowId === row.id ? "Parar" : "Camera"}
                        </button>
                        <button
                          type="button"
                          onClick={() => triggerOcrCapture(row.id)}
                          className="shrink-0 rounded-lg px-3 py-2 text-sm font-semibold border border-amber-500/60 bg-amber-500/10 text-amber-100 hover:bg-amber-500/20"
                          disabled={!!ocrBusyRowId}
                        >
                          {ocrBusyRowId === row.id ? "OCR..." : "Foto OCR"}
                        </button>
                      </div>
                      {row.itemError && <span className="text-[11px] text-red-300">{row.itemError}</span>}
                    </div>
                  </div>

                  <div>
                    <div className="text-[11px] uppercase text-zinc-400">Descricao</div>
                    <div className="w-full rounded-lg bg-zinc-900 px-2 py-2 text-base text-white leading-relaxed min-h-[52px] border border-zinc-800/70">
                      {row.descricao || <span className="text-zinc-500">Descricao</span>}
                    </div>
                  </div>

                  <div className="grid grid-cols-3 gap-2 items-end">
                    <div>
                      <div className="text-[11px] uppercase text-zinc-400">Estoque</div>
                      <div className="rounded-lg bg-zinc-900 px-3 py-2 text-sm text-zinc-200 border border-zinc-800/70">
                        {row.estoqueAtual !== null
                          ? row.estoqueAtual.toLocaleString("pt-BR", { minimumFractionDigits: 0 })
                          : "-"}
                      </div>
                    </div>

                    <div className="col-span-2">
                      <div className="text-[11px] uppercase text-zinc-400">Quantidade</div>
                      <div className="flex gap-2 items-center">
                        <input
                          value={row.quantidadeText}
                          onChange={(e) => handleRowChange(row.id, "quantidade", e.target.value)}
                          className="w-full rounded-lg bg-zinc-900 px-4 py-3 text-base text-white placeholder:text-zinc-500 focus:border focus:border-blue-500 focus:outline-none text-right border border-zinc-800/70"
                          placeholder="0,0"
                          inputMode="decimal"
                          enterKeyHint="done"
                        />
                        {showRemove && (
                          <button
                            type="button"
                            onClick={() => removeRow(row.id)}
                            className="shrink-0 rounded-full border border-red-900 bg-red-900/40 px-3 py-2 text-[11px] font-semibold text-red-100 hover:bg-red-900/60"
                          >
                            remover
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {scanError && <div className="text-sm text-red-300">{scanError}</div>}

          <div
            className={`rounded-xl border border-blue-500/40 bg-blue-950/40 p-3 space-y-2 ${
              scanningRowId ? "" : "hidden"
            }`}
          >
            <div className="text-sm font-semibold text-blue-100">Lendo codigo...</div>
            <video ref={videoRef} className="w-full rounded-lg border border-zinc-800 bg-black" autoPlay muted playsInline />
            <div className="flex items-center gap-2 text-xs text-blue-100">
              <span className="inline-flex h-2 w-2 rounded-full bg-emerald-400 animate-pulse" />
              Aponte a camera para o codigo de barras ou QR. Fecha automaticamente ao ler.
            </div>
          </div>

          <input
            ref={ocrInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            className="hidden"
            onChange={handleOcrFile}
          />
        </div>

        {success && (
          <div className="rounded-xl border border-emerald-900 bg-emerald-950 px-4 py-3 text-sm text-emerald-200">
            {success}
          </div>
        )}

        {error && (
          <div className="rounded-xl border border-red-900 bg-red-950 px-4 py-3 text-sm text-red-200">{error}</div>
        )}

        <button
          type="button"
          onClick={handleSubmit}
          disabled={!submitEnabled}
          className={`w-full rounded-2xl px-4 py-4 text-lg font-semibold text-white shadow-lg shadow-blue-500/20 ${
            submitEnabled ? "bg-blue-600 hover:bg-blue-500 active:translate-y-[1px]" : "bg-zinc-700 text-zinc-300"
          }`}
        >
          {submitting ? "Baixando..." : "Baixar Itens"}
        </button>
      </div>

      {showOsLookup && (
        <div
          className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 overflow-y-auto"
          onClick={(e) => e.target === e.currentTarget && closeOsLookup()}
        >
          <div className="min-h-full w-full flex items-start sm:items-center justify-center p-4 py-6">
            <div className="w-full max-w-2xl bg-zinc-950 border border-zinc-800 rounded-xl shadow-xl max-h-[90vh] flex flex-col overflow-hidden">
              <div className="px-5 py-4 border-b border-zinc-800 flex items-center justify-between">
                <div>
                  <div className="text-lg font-semibold">Buscar OS</div>
                  <div className="text-sm text-zinc-400">Digite numero da OS ou cliente para buscar.</div>
                </div>
                <button
                  type="button"
                  onClick={closeOsLookup}
                  className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
                >
                  Fechar
                </button>
              </div>

              <div className="px-5 py-4 space-y-3 flex-1 min-h-0 overflow-auto">
                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Buscar</div>
                  <input
                    value={osLookupTerm}
                    onChange={(e) => {
                      const value = e.target.value;
                      setOsLookupTerm(value);
                      if (osLookupDebounceRef.current) clearTimeout(osLookupDebounceRef.current);
                      osLookupDebounceRef.current = setTimeout(() => {
                        void loadOsLookup(value);
                      }, 300);
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        void loadOsLookup(osLookupTerm);
                      }
                    }}
                    placeholder="Ex: 43 ou nome do cliente"
                    className="w-full px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 text-zinc-100"
                    autoFocus
                  />
                </div>

                {osLookupLoading && <div className="text-sm text-zinc-400">Buscando...</div>}
                {osLookupError && <div className="text-sm text-red-400">{osLookupError}</div>}

                <div className="border border-zinc-800 rounded-lg overflow-hidden">
                  <table className="w-full text-sm">
                    <thead className="bg-zinc-900/70">
                      <tr className="text-zinc-200">
                        <th className="px-3 py-2 text-left">OS</th>
                        <th className="px-3 py-2 text-left">Cliente</th>
                        <th className="px-3 py-2 text-left">Descricao</th>
                        <th className="px-3 py-2 text-center">Acao</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-zinc-800">
                      {osLookupRows.map((row) => (
                        <tr key={row.id} className="hover:bg-zinc-900/40">
                          <td className="px-3 py-2">{row.numero_os ?? row.id}</td>
                          <td className="px-3 py-2">{row.cliente_nome ?? "-"}</td>
                          <td className="px-3 py-2">{row.descricao_servico ?? "-"}</td>
                          <td className="px-3 py-2 text-center">
                            <button
                              type="button"
                              onClick={() => {
                                const numero = row.numero_os ?? String(row.id);
                                setOs(numero);
                                closeOsLookup();
                              }}
                              className="px-3 py-1.5 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
                            >
                              Selecionar
                            </button>
                          </td>
                        </tr>
                      ))}
                      {!osLookupLoading && osLookupRows.length === 0 && osLookupTerm.trim() !== "" && (
                        <tr>
                          <td colSpan={4} className="px-3 py-4 text-zinc-400">
                            Nenhuma OS encontrada.
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { supabaseBrowser } from "@/lib/supabase/client";
import { useTenantEmpresa } from "@/lib/auth/useTenantEmpresa";
import { applyTenantEmpresa } from "@/lib/db/scopes";
import { usePermissions } from "@/components/auth/PermissionsProvider";
import { Can } from "@/components/auth/Can";

type Cliente = { id: number; nome: string; ativo: boolean };
type Colaborador = { id: string; nome: string; ativo: boolean };
type ServicoHH = { id: number; nome: string; preco_base: number; ativo: boolean };

type ColaboradorFuncao = {
  id: number;
  colaborador_id: string;
  servico_hh_id: number;
  ativo: boolean;
  colaboradores?: { nome: string | null } | null;
  cliente_hh_servicos?: { nome: string | null } | null;
};

export default function ColaboradorFuncaoPage() {
  const supabase = useMemo(() => {
    if (typeof window === "undefined") return null as unknown as ReturnType<typeof supabaseBrowser>;
    return supabaseBrowser();
  }, []);
  const { tenantId, empresaId } = useTenantEmpresa();
  const fixedTenantId = "3ced7cfa-efbb-4f0f-addc-2028f60d1ca7";
  const fixedEmpresaId = "f0e74f49-a127-46b4-901b-f7b37e43c690";
  const effectiveTenantId = useMemo(() => tenantId ?? fixedTenantId, [tenantId]);
  const effectiveEmpresaId = useMemo(() => empresaId ?? fixedEmpresaId, [empresaId]);
  const { has, loading: permLoading, ready } = usePermissions();
  const canView = has("apontamentos.read");

  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [colaboradores, setColaboradores] = useState<Colaborador[]>([]);
  const [servicos, setServicos] = useState<ServicoHH[]>([]);
  const [vinculos, setVinculos] = useState<ColaboradorFuncao[]>([]);

  const [clienteId, setClienteId] = useState<number | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [ok, setOk] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const [showForm, setShowForm] = useState(false);
  const [formColabId, setFormColabId] = useState<string | null>(null);
  const [formServicoId, setFormServicoId] = useState<number | null>(null);

  const loadClientes = useCallback(async () => {
    if (!tenantId || !empresaId) return;
    const { data } = await applyTenantEmpresa(
      supabase.from("clientes").select("id,nome,ativo").eq("ativo", true).order("nome", { ascending: true }),
      tenantId,
      empresaId
    );
    setClientes((data ?? []) as Cliente[]);
  }, [empresaId, supabase, tenantId]);

  const loadColaboradores = useCallback(async () => {
    if (!tenantId) return;
    const { data } = await supabase
      .from("colaboradores")
      .select("id,nome,ativo")
      .eq("ativo", true)
      .order("nome", { ascending: true });
    setColaboradores((data ?? []) as Colaborador[]);
  }, [supabase, tenantId]);

  const loadServicos = useCallback(async () => {
    if (!tenantId || !empresaId || !clienteId) {
      setServicos([]);
      return;
    }
    const { data } = await applyTenantEmpresa(
      supabase
        .from("cliente_hh_servicos")
        .select("id,nome,preco_base,ativo")
        .eq("cliente_id", clienteId)
        .eq("ativo", true)
        .order("nome", { ascending: true }),
      tenantId,
      empresaId
    );
    setServicos((data ?? []) as ServicoHH[]);
  }, [clienteId, empresaId, supabase, tenantId]);

  const loadVinculos = useCallback(async () => {
    if (!tenantId || !clienteId) {
      setVinculos([]);
      return;
    }
    const { data } = await supabase
      .from("colaborador_funcao_hh")
      .select("id,colaborador_id,servico_hh_id,ativo,colaboradores(nome),cliente_hh_servicos(nome)")
      .eq("tenant_id", tenantId)
      .eq("cliente_id", clienteId)
      .order("colaborador_id", { ascending: true });

    const mapped = (data ?? []).map((row) => {
      const r = row as Record<string, unknown>;
      const colaboradores = r.colaboradores;
      const cliente_hh_servicos = r.cliente_hh_servicos;
      return {
        id: r.id,
        colaborador_id: r.colaborador_id,
        servico_hh_id: r.servico_hh_id,
        ativo: r.ativo,
        colaboradores:
          Array.isArray(colaboradores) && colaboradores.length > 0
            ? (colaboradores[0] as unknown as ColaboradorFuncao["colaboradores"])
            : null,
        cliente_hh_servicos:
          Array.isArray(cliente_hh_servicos) && cliente_hh_servicos.length > 0
            ? (cliente_hh_servicos[0] as unknown as ColaboradorFuncao["cliente_hh_servicos"])
            : null,
      };
    });

    setVinculos(mapped as ColaboradorFuncao[]);
  }, [clienteId, supabase, tenantId]);

  useEffect(() => {
    const t = setTimeout(() => {
      void loadClientes();
      void loadColaboradores();
    }, 0);
    return () => clearTimeout(t);
  }, [loadClientes, loadColaboradores, tenantId, effectiveTenantId]);

  useEffect(() => {
    if (!clienteId) return;
    const t = setTimeout(() => {
      void loadServicos();
      void loadVinculos();
    }, 0);
    return () => clearTimeout(t);
  }, [clienteId, loadServicos, loadVinculos]);

  async function adicionarVinculo() {
    if (!tenantId || !clienteId || !formColabId || !formServicoId) {
      setErr("Preencha todos os campos.");
      return;
    }

    setBusy(true);
    setErr(null);

    const { error } = await supabase.from("colaborador_funcao_hh").insert({
      tenant_id: tenantId,
      cliente_id: clienteId,
      colaborador_id: formColabId,
      servico_hh_id: formServicoId,
      ativo: true,
    });

    setBusy(false);

    if (error) {
      if (error.message?.includes("unique")) {
        setErr("Este colaborador já tem esta função vinculada.");
      } else {
        setErr(error.message);
      }
      return;
    }

    setOk("Vínculo adicionado com sucesso!");
    setFormColabId(null);
    setFormServicoId(null);
    setShowForm(false);
    await loadVinculos();
  }

  async function removerVinculo(id: number) {
    const ok = confirm("Remover este vínculo?");
    if (!ok) return;

    setBusy(true);
    setErr(null);

    const { error } = await supabase.from("colaborador_funcao_hh").delete().eq("id", id);

    setBusy(false);

    if (error) {
      setErr(error.message);
      return;
    }

    setOk("Vínculo removido.");
    await loadVinculos();
  }

  if (!ready && permLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Carregando permissões...
      </div>
    );
  }

  if (!canView) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Acesso negado.
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-3 flex-wrap">
        <div>
          <h1 className="text-2xl font-semibold">Colaboradores - Funções HH</h1>
          <p className="text-sm text-zinc-400 mt-1">
            Vincule colaboradores às funções (especialidades) por cliente.
          </p>
        </div>

        <Can perm="apontamentos.write">
          <button
            onClick={() => {
              if (!clienteId) {
                alert("Selecione um cliente primeiro.");
                return;
              }
              setShowForm(true);
              setFormColabId(null);
              setFormServicoId(null);
            }}
            disabled={!clienteId}
            className="px-4 py-2 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white font-medium disabled:opacity-50"
          >
            Adicionar Vínculo
          </button>
        </Can>
      </div>

      <div className="border border-zinc-800 rounded-xl p-4 bg-zinc-950">
        <div className="space-y-1">
          <div className="text-xs text-zinc-400">Cliente *</div>
          <select
            aria-label="Cliente"
            className="w-full md:w-96 px-3 py-2"
            value={clienteId ?? ""}
            onChange={(e) => setClienteId(e.target.value ? Number(e.target.value) : null)}
          >
            <option value="">Selecione um cliente</option>
            {clientes.map((c) => (
              <option key={c.id} value={c.id}>
                {c.nome}
              </option>
            ))}
          </select>
        </div>
      </div>

      {err && <div className="text-sm text-red-400">{err}</div>}
      {ok && <div className="text-sm text-emerald-300">{ok}</div>}

      {clienteId && (
        <div className="border border-zinc-800 rounded-xl overflow-hidden bg-zinc-950">
          <table className="w-full text-sm">
            <thead className="bg-zinc-900/70">
              <tr className="text-zinc-200">
                <th className="px-4 py-3 text-left">Colaborador</th>
                <th className="px-4 py-3 text-left">Função (Serviço HH)</th>
                <th className="px-4 py-3 text-center">Ativo</th>
                <th className="px-4 py-3 text-center">Ações</th>
              </tr>
            </thead>

            <tbody className="divide-y divide-zinc-800">
              {vinculos.map((v) => (
                <tr key={v.id} className="hover:bg-zinc-900/40">
                  <td className="px-4 py-3 font-medium">
                    {v.colaboradores?.nome ?? `ID: ${v.colaborador_id}`}
                  </td>
                  <td className="px-4 py-3 text-zinc-300">
                    {v.cliente_hh_servicos?.nome ?? `ID: ${v.servico_hh_id}`}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <span
                      className={`inline-flex items-center px-2 py-1 rounded-md border text-xs ${
                        v.ativo
                          ? "bg-emerald-500/15 text-emerald-300 border-emerald-500/30"
                          : "bg-zinc-500/15 text-zinc-300 border-zinc-500/30"
                      }`}
                    >
                      {v.ativo ? "Sim" : "Não"}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <Can perm="apontamentos.write">
                      <button
                        onClick={() => removerVinculo(v.id)}
                        disabled={busy}
                        className="px-3 py-1.5 rounded-md border border-red-600/50 bg-red-900/20 hover:bg-red-900/30 text-red-300 text-sm"
                      >
                        Remover
                      </button>
                    </Can>
                  </td>
                </tr>
              ))}

              {vinculos.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-4 py-6 text-zinc-400">
                    Nenhum vínculo cadastrado para este cliente.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {showForm && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="w-full max-w-lg bg-zinc-950 border border-zinc-800 rounded-xl shadow-xl">
            <div className="px-5 py-4 border-b border-zinc-800 flex items-center justify-between">
              <div>
                <div className="text-lg font-semibold">Adicionar Vínculo</div>
                <div className="text-sm text-zinc-400">Vincule um colaborador a uma função de HH.</div>
              </div>
              <button
                onClick={() => setShowForm(false)}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Cancelar
              </button>
            </div>

            <div className="px-5 py-4 space-y-3">
              <div className="space-y-1">
                <div className="text-xs text-zinc-400">Colaborador *</div>
                <select
                  aria-label="Colaborador"
                  className="w-full px-3 py-2"
                  value={formColabId ?? ""}
                  onChange={(e) => setFormColabId(e.target.value || null)}
                >
                  <option value="">Selecione...</option>
                  {colaboradores.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.nome}
                    </option>
                  ))}
                </select>
              </div>

              <div className="space-y-1">
                <div className="text-xs text-zinc-400">Função (Serviço HH) *</div>
                <select
                  aria-label="Serviço HH"
                  className="w-full px-3 py-2"
                  value={formServicoId ?? ""}
                  onChange={(e) => setFormServicoId(e.target.value ? Number(e.target.value) : null)}
                >
                  <option value="">Selecione...</option>
                  {servicos.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.nome}
                    </option>
                  ))}
                </select>
              </div>

              {err && <div className="text-sm text-red-400">{err}</div>}
            </div>

            <div className="px-5 py-3 border-t border-zinc-800 flex justify-end gap-2">
              <button
                onClick={() => setShowForm(false)}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Cancelar
              </button>
              <button
                onClick={adicionarVinculo}
                disabled={busy || !formColabId || !formServicoId}
                className="px-4 py-2 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white font-medium disabled:opacity-60"
              >
                {busy ? "Adicionando..." : "Adicionar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { supabaseBrowser } from "@/lib/supabase/client";
import { useTenantEmpresa } from "@/lib/auth/useTenantEmpresa";
import { usePermissions } from "@/components/auth/PermissionsProvider";
import { applyTenant } from "@/lib/db/scopes";

type Cliente = {
  id: number;
  nome: string;
  ativo: boolean;
  habilita_hh: boolean;
};

type Colaborador = {
  id: string;
  nome: string;
  ativo: boolean;
};

type HHServico = {
  id: number;
  nome: string;
  preco_base: number;
  preco_50: number;
  preco_100: number;
};

type Vinculo = {
  id: number;
  colaborador_id: string;
  hh_servico_id: number;
  ativo: boolean;
  criado_em: string;
  atualizado_em: string;
};

type VinculoRow = Vinculo & {
  colaborador_nome?: string;
  servico_nome?: string;
};

type VinculoForm = {
  colaborador_id: string;
  hh_servico_id: number | null;
  ativo: boolean;
};

function emptyForm(): VinculoForm {
  return {
    colaborador_id: "",
    hh_servico_id: null,
    ativo: true,
  };
}

export default function ColaboradoresClientePage() {
  const supabase = useMemo(() => {
    if (typeof window === "undefined") return null as unknown as ReturnType<typeof supabaseBrowser>;
    return supabaseBrowser();
  }, []);
  const { tenantId, empresaId } = useTenantEmpresa();
  const fixedTenantId = "3ced7cfa-efbb-4f0f-addc-2028f60d1ca7";
  const fixedEmpresaId = "f0e74f49-a127-46b4-901b-f7b37e43c690";
  const effectiveTenantId = useMemo(() => tenantId ?? fixedTenantId, [tenantId]);
  const effectiveEmpresaId = useMemo(() => empresaId ?? fixedEmpresaId, [empresaId]);
  const { has, loading: permissionsLoading, ready } = usePermissions();
  const canRead = Boolean(has("admin.manage_users")) || Boolean(has("financeiro.read")) || Boolean(has("apontamentos.read"));
  const canWrite = Boolean(has("admin.manage_users")) || Boolean(has("financeiro.read"));

  const [clientes, setClientes] = useState<Cliente[]>([]);
  const [colaboradores, setColaboradores] = useState<Colaborador[]>([]);
  const [servicos, setServicos] = useState<HHServico[]>([]);
  const [vinculos, setVinculos] = useState<VinculoRow[]>([]);

  const [clienteId, setClienteId] = useState<number | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [ok, setOk] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [form, setForm] = useState<VinculoForm>(emptyForm());

  async function loadClientes() {
    if (!tenantId) return;
    try {
      const { data, error } = await applyTenant(
        supabase
          .from("clientes")
          .select("id,nome,ativo,habilita_hh")
          .eq("ativo", true)
          .eq("habilita_hh", true)
          .order("nome", { ascending: true }),
        tenantId
      );
      if (error) throw error;
      setClientes((data ?? []) as Cliente[]);
    } catch (e: unknown) {
      console.warn("Erro ao carregar clientes:", e);
    }
  }

  async function loadColaboradores() {
    if (!tenantId) return;
    try {
      const { data, error } = await applyTenant(
        supabase.from("colaboradores").select("id,nome,ativo").eq("ativo", true).order("nome", { ascending: true }),
        tenantId
      );
      if (error) throw error;
      setColaboradores((data ?? []) as Colaborador[]);
    } catch (e: unknown) {
      console.warn("Erro ao carregar colaboradores:", e);
    }
  }

  async function loadServicos() {
    if (!tenantId || !clienteId) {
      setServicos([]);
      return;
    }
    try {
      const { data, error } = await supabase
        .from("cliente_hh_servicos")
        .select("id,nome,preco_base,preco_50,preco_100")
        .eq("tenant_id", tenantId)
        .eq("cliente_id", clienteId)
        .eq("ativo", true)
        .order("nome", { ascending: true });
      if (error) throw error;
      setServicos((data ?? []) as HHServico[]);
    } catch (e: unknown) {
      console.warn("Erro ao carregar serviços HH:", e);
    }
  }

  async function loadVinculos() {
    if (!tenantId || !clienteId) {
      setVinculos([]);
      return;
    }
    try {
      const { data, error } = await applyTenant(
        supabase
          .from("colaborador_cliente_funcao")
          .select("id,colaborador_id,hh_servico_id,ativo,criado_em,atualizado_em")
          .eq("cliente_id", clienteId)
          .order("criado_em", { ascending: false }),
        tenantId
      );
      if (error) throw error;

      const vinculosRaw = (data ?? []) as Vinculo[];

      // Enriquecer com nomes
      const colaboradorMap = new Map(colaboradores.map((c) => [c.id, c.nome]));
      const servicoMap = new Map(servicos.map((s) => [s.id, s.nome]));

      const enriched: VinculoRow[] = vinculosRaw.map((v) => ({
        ...v,
        colaborador_nome: colaboradorMap.get(v.colaborador_id) ?? `ID: ${v.colaborador_id}`,
        servico_nome: servicoMap.get(v.hh_servico_id) ?? `ID: ${v.hh_servico_id}`,
      }));

      setVinculos(enriched);
    } catch (e: unknown) {
      console.warn("Erro ao carregar vínculos:", e);
    }
  }

  function novoVinculo() {
    setEditingId(null);
    setForm(emptyForm());
    setErr(null);
    setOk(null);
    setShowModal(true);
  }

  function editarVinculo(v: VinculoRow) {
    setEditingId(v.id);
    setForm({
      colaborador_id: v.colaborador_id,
      hh_servico_id: v.hh_servico_id,
      ativo: v.ativo,
    });
    setErr(null);
    setOk(null);
    setShowModal(true);
  }

  function fecharModal() {
    setShowModal(false);
    setEditingId(null);
    setForm(emptyForm());
    setErr(null);
  }

  async function salvar() {
    if (!tenantId || !clienteId || !canWrite) {
      setErr("Sem permissão para salvar.");
      return;
    }

    if (!form.colaborador_id || form.colaborador_id.trim() === "") {
      setErr("Selecione um colaborador.");
      return;
    }

    if (!form.hh_servico_id) {
      setErr("Selecione uma função/serviço HH.");
      return;
    }

    setBusy(true);
    setErr(null);
    setOk(null);

    try {
      const { data: sess } = await supabase.auth.getSession();
      const userEmail = sess.session?.user?.email ?? null;

      // Validar que colaborador existe
      console.log("Validando colaborador_id:", form.colaborador_id);
      const { data: colabCheck, error: colabErr } = await applyTenant(
        supabase.from("colaboradores").select("id").eq("id", form.colaborador_id).maybeSingle(),
        tenantId
      );
      
      if (colabErr) {
        console.error("Erro ao validar colaborador:", colabErr);
        setErr(`Erro ao validar colaborador: ${colabErr.message}`);
        setBusy(false);
        return;
      }
      
      if (!colabCheck) {
        console.error("Colaborador não encontrado:", form.colaborador_id);
        setErr("Colaborador selecionado não existe. Recarregue a página e tente novamente.");
        setBusy(false);
        return;
      }
      
      console.log("Colaborador validado:", colabCheck);

      // NÃO passar tenant_id no payload - virá automaticamente do contexto RLS
      const payload = {
        cliente_id: clienteId,
        colaborador_id: form.colaborador_id,
        hh_servico_id: form.hh_servico_id,
        ativo: form.ativo,
        atualizado_em: new Date().toISOString(),
      };

      console.log("Payload completo:", payload);

      let error;

      if (editingId) {
        // Atualizar
        const res = await applyTenant(
          supabase.from("colaborador_cliente_funcao").update(payload).eq("id", editingId),
          tenantId
        );
        console.log("Resposta UPDATE completa:", res);
        console.log("res.data:", res.data);
        console.log("res.error:", res.error);
        error = res.error;
      } else {
        // Criar novo - tenant_id virá do contexto via trigger ou default
        const res = await applyTenant(
          supabase.from("colaborador_cliente_funcao").insert({
            ...payload,
            criado_por: userEmail,
            criado_em: new Date().toISOString(),
          }),
          tenantId
        );
        console.log("Resposta INSERT completa:", res);
        console.log("res.data:", res.data);
        console.log("res.error:", res.error);
        error = res.error;
      }

      if (error) {
        console.error("Erro Supabase completo:", error);
        console.error("Código:", error.code);
        console.error("Mensagem:", error.message);
        console.error("Detalhes:", error.details);
        console.error("Hint:", error.hint);
        
        // Se for erro de constraint unique, mensagem amigável
        if (error.code === "23505" || error.message?.toLowerCase().includes("unique")) {
          throw new Error("Este colaborador já está vinculado a este serviço neste cliente.");
        }
        // Se for erro de RLS, mensagem clara
        if (error.code === "42501" || error.message?.toLowerCase().includes("row-level security")) {
          throw new Error("Sem permissão para salvar vínculo. Verifique suas permissões (apontamentos.write).");
        }
        throw new Error(error.message || "Erro desconhecido do banco de dados");
      }

      setOk(editingId ? "Vínculo atualizado!" : "Vínculo criado!");
      fecharModal();
      await loadVinculos();
    } catch (e: unknown) {
      console.error("Erro detalhado ao salvar vínculo:", e);
      console.error("Tipo do erro:", typeof e);
      console.error("JSON do erro:", JSON.stringify(e, null, 2));
      
      let message = "Erro ao salvar vínculo.";
      if (e instanceof Error) {
        message = e.message;
      } else if (e && typeof e === "object" && "message" in e) {
        message = String((e as { message: unknown }).message);
      }
      setErr(message);
    } finally {
      setBusy(false);
    }
  }

  async function excluir(id: number) {
    const ok = confirm("Deseja realmente excluir este vínculo?");
    if (!ok) return;

    if (!tenantId || !canWrite) {
      setErr("Sem permissão para excluir.");
      return;
    }

    setBusy(true);
    setErr(null);
    setOk(null);

    try {
      // Soft delete: apenas desativa
      const { error } = await applyTenant(
        supabase
          .from("colaborador_cliente_funcao")
          .update({ ativo: false, atualizado_em: new Date().toISOString() })
          .eq("id", id),
        tenantId
      );

      if (error) throw error;

      setOk("Vínculo desativado!");
      await loadVinculos();
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : "Erro ao excluir vínculo.";
      setErr(message);
    } finally {
      setBusy(false);
    }
  }

  async function toggleAtivo(id: number, novoStatus: boolean) {
    if (!tenantId || !canWrite) {
      setErr("Sem permissão para alterar status.");
      return;
    }

    setBusy(true);
    setErr(null);
    setOk(null);

    try {
      const { error } = await applyTenant(
        supabase
          .from("colaborador_cliente_funcao")
          .update({ ativo: novoStatus, atualizado_em: new Date().toISOString() })
          .eq("id", id),
        tenantId
      );

      if (error) throw error;

      setOk(novoStatus ? "Vínculo ativado!" : "Vínculo desativado!");
      await loadVinculos();
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : "Erro ao alterar status.";
      setErr(message);
    } finally {
      setBusy(false);
    }
  }

  useEffect(() => {
    void loadClientes();
    void loadColaboradores();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tenantId, effectiveTenantId]);

  useEffect(() => {
    if (!clienteId) {
      setServicos([]);
      setVinculos([]);
      return;
    }
    void loadServicos();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [clienteId, tenantId, empresaId]);

  useEffect(() => {
    if (servicos.length > 0 && clienteId) {
      void loadVinculos();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [servicos, clienteId, tenantId]);

  if (!ready && permissionsLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Carregando permissões...
      </div>
    );
  }

  if (!canRead) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Acesso negado.
      </div>
    );
  }

  const clienteNome = clientes.find((c) => c.id === clienteId)?.nome ?? "";

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-3 flex-wrap">
        <div>
          <h1 className="text-2xl font-semibold">Colaboradores × Cliente × Função HH</h1>
          <p className="text-sm text-zinc-400 mt-1">
            Gerencie os vínculos entre colaboradores e funções/serviços HH por cliente.
          </p>
        </div>
      </div>

      {err && <div className="text-sm text-red-400">{err}</div>}
      {ok && <div className="text-sm text-emerald-300">{ok}</div>}

      <div className="border border-zinc-800 rounded-xl p-4 bg-zinc-950">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="space-y-1">
            <label className="text-xs text-zinc-400">Cliente (HH habilitado) *</label>
            <select
              aria-label="Selecionar cliente"
              className="w-full px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900"
              value={clienteId ?? ""}
              onChange={(e) => setClienteId(e.target.value ? Number(e.target.value) : null)}
            >
              <option value="">Selecione um cliente...</option>
              {clientes.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.nome}
                </option>
              ))}
            </select>
            {clientes.length === 0 && (
              <div className="text-xs text-amber-300 mt-1">
                Nenhum cliente com HH habilitado.{" "}
                <a href="/clientes" className="underline hover:text-amber-200">
                  Habilite HH em um cliente →
                </a>
              </div>
            )}
          </div>
        </div>

        {clienteId && servicos.length === 0 && (
          <div className="mt-4 text-sm text-amber-300">
            O cliente &quot;{clienteNome}&quot; não possui serviços HH cadastrados.{" "}
            <a
              href={`/cadastros/hh/servicos-cliente?cliente_id=${clienteId}`}
              className="underline hover:text-amber-200"
            >
              Cadastre serviços primeiro →
            </a>
          </div>
        )}
      </div>

      {clienteId && servicos.length > 0 && (
        <>
          <div className="flex items-center justify-between gap-3">
            <div className="text-sm text-zinc-300">
              Vínculos de &quot;{clienteNome}&quot; ({vinculos.length})
            </div>
            {canWrite && (
              <button
                onClick={novoVinculo}
                className="px-4 py-2 rounded-md bg-emerald-300 text-emerald-950 hover:bg-emerald-200 font-medium"
              >
                + Novo Vínculo
              </button>
            )}
          </div>

          <div className="border border-zinc-800 rounded-xl overflow-hidden bg-zinc-950">
            <table className="w-full text-sm">
              <thead className="bg-zinc-900/70">
                <tr className="text-left text-zinc-200">
                  <th className="px-4 py-3">Colaborador</th>
                  <th className="px-4 py-3">Função / Serviço HH</th>
                  <th className="px-4 py-3 text-center">Status</th>
                  <th className="px-4 py-3 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800">
                {vinculos.map((v) => (
                  <tr key={v.id} className={v.ativo ? "hover:bg-zinc-900/40" : "bg-zinc-900/20 opacity-60"}>
                    <td className="px-4 py-3 font-medium text-zinc-200">{v.colaborador_nome}</td>
                    <td className="px-4 py-3 text-zinc-300">{v.servico_nome}</td>
                    <td className="px-4 py-3 text-center">
                      <span
                        className={
                          v.ativo
                            ? "inline-flex px-2 py-1 rounded-md border text-xs bg-emerald-500/15 text-emerald-300 border-emerald-500/30"
                            : "inline-flex px-2 py-1 rounded-md border text-xs bg-zinc-500/15 text-zinc-400 border-zinc-500/30"
                        }
                      >
                        {v.ativo ? "Ativo" : "Inativo"}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <div className="flex items-center justify-center gap-2">
                        {canWrite && (
                          <>
                            <button
                              onClick={() => editarVinculo(v)}
                              className="px-3 py-1.5 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800 text-xs"
                            >
                              Editar
                            </button>
                            <button
                              onClick={() => toggleAtivo(v.id, !v.ativo)}
                              className="px-3 py-1.5 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800 text-xs"
                            >
                              {v.ativo ? "Desativar" : "Ativar"}
                            </button>
                            <button
                              onClick={() => excluir(v.id)}
                              className="px-3 py-1.5 rounded-md border border-red-700 bg-red-900/20 hover:bg-red-900/40 text-red-300 text-xs"
                            >
                              Excluir
                            </button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}

                {vinculos.length === 0 && (
                  <tr>
                    <td colSpan={4} className="px-4 py-6 text-zinc-400 text-center">
                      Nenhum vínculo cadastrado para este cliente.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}

      {/* Modal Criar/Editar Vínculo */}
      {showModal && (
        <div
          className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50"
          onClick={(e) => e.target === e.currentTarget && fecharModal()}
        >
          <div
            className="w-full max-w-2xl bg-zinc-950 border border-zinc-800 rounded-xl shadow-xl overflow-hidden"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="px-5 py-4 border-b border-zinc-800 flex items-center justify-between bg-zinc-900/40">
              <div>
                <div className="text-lg font-semibold">
                  {editingId ? `Editar Vínculo #${editingId}` : "Novo Vínculo"}
                </div>
                <div className="text-sm text-zinc-400">
                  Cliente: {clienteNome}
                </div>
              </div>
              <button
                onClick={fecharModal}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Fechar
              </button>
            </div>

            <div className="px-5 py-4 space-y-4">
              <div className="grid grid-cols-1 gap-3">
                <div className="space-y-1">
                  <label className="text-xs text-zinc-400">Colaborador *</label>
                  <select
                    aria-label="Colaborador"
                    className="w-full px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900"
                    value={form.colaborador_id}
                    onChange={(e) => setForm((prev) => ({ ...prev, colaborador_id: e.target.value }))}
                  >
                    <option value="">Selecione...</option>
                    {colaboradores.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.nome}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1">
                  <label className="text-xs text-zinc-400">Função / Serviço HH *</label>
                  <select
                    aria-label="Serviço HH"
                    className="w-full px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900"
                    value={form.hh_servico_id ?? ""}
                    onChange={(e) =>
                      setForm((prev) => ({ ...prev, hh_servico_id: e.target.value ? Number(e.target.value) : null }))
                    }
                  >
                    <option value="">Selecione...</option>
                    {servicos.map((s) => (
                      <option key={s.id} value={s.id}>
                        {s.nome} (Base: R$ {s.preco_base.toFixed(2)})
                      </option>
                    ))}
                  </select>
                </div>

                <div className="border border-zinc-800 rounded-lg px-4 py-3 bg-zinc-900/40">
                  <label className="flex items-center gap-2 text-sm text-zinc-300">
                    <input
                      type="checkbox"
                      checked={form.ativo}
                      onChange={(e) => setForm((prev) => ({ ...prev, ativo: e.target.checked }))}
                      className="h-4 w-4"
                    />
                    Ativo
                  </label>
                  <div className="text-xs text-zinc-400 mt-1">
                    Vínculos inativos não aparecem nos lançamentos de HH.
                  </div>
                </div>
              </div>

              {err && <div className="text-sm text-red-400">{err}</div>}
            </div>

            <div className="px-5 py-3 border-t border-zinc-800 bg-zinc-950 flex justify-end gap-2">
              <button
                onClick={fecharModal}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Cancelar
              </button>
              <button
                onClick={salvar}
                disabled={busy || !canWrite}
                className="px-4 py-2 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white font-medium disabled:opacity-60"
              >
                {busy ? "Salvando..." : "Salvar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { supabaseBrowser } from "@/lib/supabase/client";
import { useTenantEmpresa } from "@/lib/auth/useTenantEmpresa";
import { usePermissions } from "@/components/auth/PermissionsProvider";
import { Can } from "@/components/auth/Can";
import { parseDecimalBR } from "@/lib/decimal";

type HHPreco = {
  id: number;
  descricao: string;
  nivel: string;
  categoria: string;
  preco_base: number;
  preco_50: number;
  preco_100: number;
  ativo: boolean;
  criado_em: string;
  atualizado_em: string;
};

type HHPrecoForm = {
  descricao: string;
  nivel: string;
  categoria: string;
  preco_base: number;
  preco_50: number;
  preco_100: number;
  ativo: boolean;
};

export default function EspecialidadesPage() {
  const supabase = useMemo(() => {
    if (typeof window === "undefined") return null as unknown as ReturnType<typeof supabaseBrowser>;
    return supabaseBrowser();
  }, []);
  const { has, loading: permLoading, ready } = usePermissions();
  const canView = has("os.read") || has("admin.manage_users") || has("financeiro.read");
  const canEdit = has("os.write") || has("admin.manage_users") || has("financeiro.read");
  const canDelete = has("os.delete") || has("admin.manage_users");

  const [rows, setRows] = useState<HHPreco[]>([]);
  const [err, setErr] = useState<string | null>(null);
  const [ok, setOk] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const [q, setQ] = useState("");
  const [filterCategoria, setFilterCategoria] = useState<string>("todas");
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [form, setForm] = useState<HHPrecoForm>({
    descricao: "",
    nivel: "I",
    categoria: "montador",
    preco_base: 0,
    preco_50: 0,
    preco_100: 0,
    ativo: true,
  });

  async function load() {
    setErr(null);

    // hh_tabela_precos é global (sem tenant_id)
    let query = supabase.from("hh_tabela_precos").select("*").order("categoria", { ascending: true }).order("nivel", { ascending: true });

    const term = q.trim().toLowerCase();
    if (term) {
      query = query.ilike("descricao", `%${term}%`);
    }

    if (filterCategoria !== "todas") {
      query = query.eq("categoria", filterCategoria);
    }

    const { data, error } = await query;
    if (error) return setErr(error.message);
    setRows((data ?? []) as HHPreco[]);
  }

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [q, filterCategoria]);

  function startNew() {
    setOk(null);
    setErr(null);
    if (!canEdit) {
      setErr("Sem permissão para criar especialidades.");
      return;
    }
    setEditingId(null);
    setForm({
      descricao: "",
      nivel: "I",
      categoria: "montador",
      preco_base: 0,
      preco_50: 0,
      preco_100: 0,
      ativo: true,
    });
    setShowForm(true);
  }

  function startEdit(r: HHPreco) {
    setOk(null);
    setErr(null);
    if (!canEdit) {
      setErr("Sem permissão para editar especialidades.");
      return;
    }
    setEditingId(r.id);
    setForm({
      descricao: r.descricao,
      nivel: r.nivel,
      categoria: r.categoria,
      preco_base: Number(r.preco_base),
      preco_50: Number(r.preco_50),
      preco_100: Number(r.preco_100),
      ativo: r.ativo,
    });
    setShowForm(true);
  }

  function closeForm() {
    setShowForm(false);
    setEditingId(null);
    setForm({
      descricao: "",
      nivel: "I",
      categoria: "montador",
      preco_base: 0,
      preco_50: 0,
      preco_100: 0,
      ativo: true,
    });
  }

  async function save() {
    setOk(null);
    setErr(null);
    if (!canEdit) {
      setErr("Sem permissão para salvar especialidades.");
      return;
    }

    if (!form.descricao.trim()) return setErr("Descrição é obrigatória.");
    if (form.preco_base <= 0) return setErr("Preço base deve ser maior que zero.");

    setBusy(true);

    const payload = {
      descricao: form.descricao.trim(),
      nivel: form.nivel,
      categoria: form.categoria,
      preco_base: Number(form.preco_base),
      preco_50: Number(form.preco_50),
      preco_100: Number(form.preco_100),
      ativo: form.ativo,
      atualizado_em: new Date().toISOString(),
    };

    let error: { message?: string } | null = null;

    if (editingId) {
      const res = await supabase.from("hh_tabela_precos").update(payload).eq("id", editingId);
      error = res.error;
    } else {
      const res = await supabase.from("hh_tabela_precos").insert({ ...payload, criado_em: new Date().toISOString() });
      error = res.error;
    }

    setBusy(false);
    if (error) return setErr(error.message ?? "Erro ao salvar.");

    setOk(editingId ? "Especialidade atualizada!" : "Especialidade criada!");
    closeForm();
    await load();
  }

  async function handleDelete(id: number) {
    if (!canDelete) {
      setErr("Sem permissão para excluir especialidades.");
      return;
    }

    const ok = confirm("Tem certeza que deseja excluir esta especialidade?");
    if (!ok) return;

    setBusy(true);
    setErr(null);
    setOk(null);

    const { error } = await supabase.from("hh_tabela_precos").delete().eq("id", id);

    setBusy(false);
    if (error) return setErr(error.message);

    setOk("Especialidade excluída.");
    await load();
  }

  if (!ready && permLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Carregando permissões...
      </div>
    );
  }

  if (!canView) {
    return (
      <div className="min-h-screen flex items-center justify-center text-zinc-300">
        Acesso negado.
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-3 flex-wrap">
        <div>
          <h1 className="text-2xl font-semibold">Tabela de Preços HH (Global)</h1>
          <p className="text-sm text-zinc-400 mt-1">
            Cadastro de especialidades e preços-base para Homem-Hora. Estes valores serão copiados para cada cliente.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={load}
            className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
          >
            Atualizar
          </button>
          <Can perm="os.write">
            <button
              onClick={startNew}
              className="px-4 py-2 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white font-medium"
            >
              Nova Especialidade
            </button>
          </Can>
        </div>
      </div>

      <div className="border border-zinc-800 rounded-xl p-4 bg-zinc-950">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="space-y-1">
            <div className="text-xs text-zinc-400">Buscar por descrição</div>
            <input
              aria-label="Buscar especialidade"
              className="w-full px-3 py-2"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              placeholder="Digite parte da descrição..."
            />
          </div>
          <div className="space-y-1">
            <div className="text-xs text-zinc-400">Categoria</div>
            <select
              aria-label="Filtrar por categoria"
              className="w-full px-3 py-2"
              value={filterCategoria}
              onChange={(e) => setFilterCategoria(e.target.value)}
            >
              <option value="todas">Todas</option>
              <option value="montador">Montador</option>
              <option value="comando">Comando</option>
              <option value="automacao">Automação</option>
              <option value="mecanica">Mecânica</option>
            </select>
          </div>
        </div>

        {err && <div className="text-sm text-red-400 mt-3">{err}</div>}
        {ok && <div className="text-sm text-emerald-300 mt-3">{ok}</div>}
      </div>

      <div className="border border-zinc-800 rounded-xl overflow-hidden bg-zinc-950">
        <div className="overflow-auto">
          <table className="w-full text-sm min-w-[900px]">
            <thead className="bg-zinc-900/70">
              <tr className="text-zinc-200">
                <th className="px-4 py-3 text-left">Descrição</th>
                <th className="px-4 py-3 text-center">Nível</th>
                <th className="px-4 py-3 text-center">Categoria</th>
                <th className="px-4 py-3 text-right">Preço Base</th>
                <th className="px-4 py-3 text-right">50%</th>
                <th className="px-4 py-3 text-right">100%</th>
                <th className="px-4 py-3 text-center">Ativo</th>
                <th className="px-4 py-3 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-zinc-800">
              {rows.map((r) => (
                <tr key={r.id} className="hover:bg-zinc-900/40">
                  <td className="px-4 py-3 font-medium">{r.descricao}</td>
                  <td className="px-4 py-3 text-center">
                    <span className="inline-flex items-center px-2 py-1 rounded-md border border-zinc-700 bg-zinc-900 text-xs">
                      {r.nivel}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center capitalize text-zinc-300">{r.categoria}</td>
                  <td className="px-4 py-3 text-right tabular-nums text-zinc-200">
                    R$ {Number(r.preco_base).toFixed(2)}
                  </td>
                  <td className="px-4 py-3 text-right tabular-nums text-zinc-200">
                    R$ {Number(r.preco_50).toFixed(2)}
                  </td>
                  <td className="px-4 py-3 text-right tabular-nums text-zinc-200">
                    R$ {Number(r.preco_100).toFixed(2)}
                  </td>
                  <td className="px-4 py-3 text-center">
                    <span
                      className={`inline-flex items-center px-2 py-1 rounded-md border text-xs ${
                        r.ativo
                          ? "bg-emerald-500/15 text-emerald-300 border-emerald-500/30"
                          : "bg-zinc-500/15 text-zinc-300 border-zinc-500/30"
                      }`}
                    >
                      {r.ativo ? "Sim" : "Não"}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="flex items-center justify-center gap-2">
                      <Can perm="os.write">
                        <button
                          onClick={() => startEdit(r)}
                          className="px-3 py-1.5 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
                        >
                          Editar
                        </button>
                      </Can>
                      <Can perm="os.delete">
                        <button
                          onClick={() => handleDelete(r.id)}
                          disabled={busy}
                          className="px-3 py-1.5 rounded-md border border-red-700 bg-red-900/30 hover:bg-red-900/50 text-red-300 disabled:opacity-60"
                        >
                          Excluir
                        </button>
                      </Can>
                    </div>
                  </td>
                </tr>
              ))}

              {rows.length === 0 && (
                <tr>
                  <td colSpan={8} className="px-4 py-6 text-zinc-400">
                    Nenhuma especialidade encontrada.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="w-full max-w-2xl bg-zinc-950 border border-zinc-800 rounded-xl shadow-xl">
            <div className="px-5 py-4 border-b border-zinc-800 flex items-center justify-between">
              <div>
                <div className="text-lg font-semibold">
                  {editingId ? "Editar Especialidade" : "Nova Especialidade"}
                </div>
                <div className="text-sm text-zinc-400">Preencha os campos abaixo.</div>
              </div>
              <button
                onClick={closeForm}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Cancelar
              </button>
            </div>

            <div className="px-5 py-4 space-y-3">
              <div className="space-y-1">
                <div className="text-xs text-zinc-400">Descrição *</div>
                <input
                  aria-label="Descrição"
                  className="w-full px-3 py-2"
                  value={form.descricao}
                  onChange={(e) => setForm((s) => ({ ...s, descricao: e.target.value }))}
                  placeholder="Ex: MAO-DE-OBRA ELETRICISTA MONTADOR HH (NIVEL I)"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Nível *</div>
                  <select
                    aria-label="Nível"
                    className="w-full px-3 py-2"
                    value={form.nivel}
                    onChange={(e) => setForm((s) => ({ ...s, nivel: e.target.value }))}
                  >
                    <option value="I">Nível I</option>
                    <option value="II">Nível II</option>
                    <option value="III">Nível III</option>
                  </select>
                </div>

                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Categoria *</div>
                  <select
                    aria-label="Categoria"
                    className="w-full px-3 py-2"
                    value={form.categoria}
                    onChange={(e) => setForm((s) => ({ ...s, categoria: e.target.value }))}
                  >
                    <option value="montador">Montador</option>
                    <option value="comando">Comando</option>
                    <option value="automacao">Automação</option>
                    <option value="mecanica">Mecânica</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Preço Base (R$) *</div>
                  <input
                    type="text"
                    inputMode="decimal"
                    aria-label="Preço base"
                    className="w-full px-3 py-2"
                    value={form.preco_base}
                    onChange={(e) => setForm((s) => ({ ...s, preco_base: parseDecimalBR(e.target.value) || 0 }))}
                    placeholder="0,00"
                  />
                </div>

                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Preço 50% (R$) *</div>
                  <input
                    type="text"
                    inputMode="decimal"
                    aria-label="Preço 50%"
                    className="w-full px-3 py-2"
                    value={form.preco_50}
                    onChange={(e) => setForm((s) => ({ ...s, preco_50: parseDecimalBR(e.target.value) || 0 }))}
                    placeholder="0,00"
                  />
                </div>

                <div className="space-y-1">
                  <div className="text-xs text-zinc-400">Preço 100% (R$) *</div>
                  <input
                    type="text"
                    inputMode="decimal"
                    aria-label="Preço 100%"
                    className="w-full px-3 py-2"
                    value={form.preco_100}
                    onChange={(e) => setForm((s) => ({ ...s, preco_100: parseDecimalBR(e.target.value) || 0 }))}
                    placeholder="0,00"
                  />
                </div>
              </div>

              <div className="flex items-center gap-2 pt-2">
                <input
                  type="checkbox"
                  checked={form.ativo}
                  onChange={(e) => setForm((s) => ({ ...s, ativo: e.target.checked }))}
                  id="ativo-check"
                />
                <label htmlFor="ativo-check" className="text-sm text-zinc-200">
                  Ativo
                </label>
              </div>

              {err && <div className="text-sm text-red-400">{err}</div>}
            </div>

            <div className="px-5 py-3 border-t border-zinc-800 flex justify-end gap-2">
              <button
                onClick={closeForm}
                className="px-3 py-2 rounded-md border border-zinc-700 bg-zinc-900 hover:bg-zinc-800"
              >
                Cancelar
              </button>
              <button
                onClick={save}
                disabled={busy || !canEdit}
                className="px-4 py-2 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white font-medium disabled:opacity-60"
              >
                {busy ? "Salvando..." : "Salvar"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import { supabaseBrowser } from "@/lib/supabase/client";
import { useTenantEmpresaContext } from "@/lib/auth/TenantEmpresaProvider";
import { useIsAdminTenant } from "@/lib/auth/useIsAdminTenant";
import type { CapabilityKey } from "@/lib/auth/capabilities";
import AdminDebugPanel from "./AdminDebugPanel";

const isDev = process.env.NODE_ENV !== "production";
const logError = (...args: unknown[]) => {
  if (isDev) console.warn(...args);
};

export default function AppShell({ children }: { children: React.ReactNode }) {
  const supabase = useMemo(() => {
    if (typeof window === "undefined") return null as unknown as ReturnType<typeof supabaseBrowser>;
    return supabaseBrowser();
  }, []);
  const te = useTenantEmpresaContext();

  const router = useRouter();
  const pathname = usePathname();

  const isPublic = pathname === "/login";
  const isFullWidth = pathname === "/itens" || pathname === "/financeiro/contas-pagar/aprovacoes";
  const hideHeader = pathname?.startsWith("/projetos") || pathname?.startsWith("/execucao");

  const tenantId = te.tenantId;
  const empresaId = te.empresaId;
  const empresas = te.empresas;

  const { isAdmin: isTenantAdmin, loading: adminLoading } = useIsAdminTenant(tenantId ?? null);
  const didAutoSelectEmpresaRef = useRef(false);

  const effectiveEmpresa = useMemo(() => {
    if (empresaId) return empresas.find((e) => e.id === empresaId) ?? null;
    if (empresas.length === 1) return empresas[0];
    return null;
  }, [empresaId, empresas]);

  useEffect(() => {
    if (te.sessionUserId === undefined) return;
    const isAuthed = Boolean(te.sessionUserId);
    if (!isAuthed && !isPublic) router.replace("/login");
    if (isAuthed && isPublic) router.replace("/");
  }, [isPublic, router, te.sessionUserId]);

  useEffect(() => {
    if (te.sessionUserId === null) {
      didAutoSelectEmpresaRef.current = false;
    }
  }, [te.sessionUserId]);

  useEffect(() => {
    if (didAutoSelectEmpresaRef.current) return;
    if (!te.sessionUserId) return; // só quando logado
    if (!empresaId && empresas.length === 1) {
      didAutoSelectEmpresaRef.current = true;
      void te.setEmpresaId(empresas[0].id);
    }
  }, [empresaId, empresas, te.sessionUserId, te.setEmpresaId]);

  const [openMenu, setOpenMenu] = useState<"os" | "estoque" | "financeiro" | "cadastro" | "admin" | null>(null);
  const navRef = useRef<HTMLDivElement | null>(null);
  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const toggleMenu = (key: "os" | "estoque" | "financeiro" | "cadastro" | "admin" | null) =>
    setOpenMenu((prev) => (prev === key ? null : key));

  const openWithHover = (key: "os" | "estoque" | "financeiro" | "cadastro" | "admin") => {
    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
    setOpenMenu(key);
  };

  const scheduleClose = () => {
    if (closeTimerRef.current) clearTimeout(closeTimerRef.current);
    closeTimerRef.current = setTimeout(() => setOpenMenu(null), 150);
  };

  const can = (k: CapabilityKey) => {
    if (te.capabilities === null) return true;
    return te.has(k) ?? false;
  };

  const canAccessOs = can("os.read");
  const canExecuteOs = can("os_rpcs.execute");
  const canAccessApontamentos = can("apontamentos.read");
  const canAccessEstoque = can("estoque.read") || can("estoque.write");
  const canAccessCadastroItens = can("cad_itens.write") || can("estoque.read") || can("os.read");
  const canImportXml = can("xml_import.execute");
  const canAccessFinanceiro = can("financeiro.read");
  const canAccessAdmin = can("admin.manage_users");
  const shouldShowAdmin = isTenantAdmin && (!adminLoading ? canAccessAdmin : true);
  const adminReason = useMemo(() => {
    if (shouldShowAdmin) return "ok";
    const reasons: string[] = [];
    if (te.sessionUserId === undefined) reasons.push("sessionUserId=undefined");
    if (te.sessionUserId === null) reasons.push("not authenticated");
    if (!te.tenantId) reasons.push("tenantId missing");
    if (adminLoading) reasons.push("adminLoading");
    if (!isTenantAdmin) reasons.push("isAdminTenant=false");
    if (!adminLoading && isTenantAdmin && !canAccessAdmin) reasons.push("can(admin.manage_users)=false");
    return reasons.join(", ") || "unknown";
  }, [adminLoading, canAccessAdmin, isTenantAdmin, shouldShowAdmin, te.sessionUserId, te.tenantId]);
  const canAccessCadastros = can("admin.manage_users") || can("financeiro.read");
  const canAccessContratos = can("admin.manage_users") || can("financeiro.read") || can("apontamentos.read");
  const canAccessColaboradores = can("admin.manage_users") || can("financeiro.read");
  const canAccessClientesCad = can("admin.manage_users") || can("financeiro.read") || can("cad_clientes.write");
  const canAccessFornecedoresCad =
    can("admin.manage_users") ||
    can("financeiro.read") ||
    can("cad_fornecedores.write") ||
    can("estoque.read") ||
    can("estoque.write");

  async function logout() {
    try {
      await supabase.auth.signOut();
    } catch (e) {
      logError("Erro ao sair", e);
    } finally {
      router.replace("/login");
      if (typeof window !== "undefined") window.location.href = "/login";
    }
  }

  if (isPublic) return <>{children}</>;

  return (
    <div className="min-h-screen">
      {!hideHeader && (
        <header className="sticky top-0 z-50 border-b border-zinc-800 bg-zinc-950/80 backdrop-blur">
          <div className="mx-auto max-w-6xl px-4 py-3 flex items-center justify-between" ref={navRef}>
            <div className="flex items-center gap-4">
              <Link href="/" className="font-semibold tracking-tight text-zinc-100">
                Home
              </Link>

              <nav className="relative flex flex-wrap items-center gap-4 text-sm text-zinc-200">
                {canAccessOs && (
                  <div className="relative" onMouseEnter={() => openWithHover("os")} onMouseLeave={scheduleClose}>
                    <button
                      type="button"
                      onClick={() => toggleMenu("os")}
                      className="px-3 py-1 rounded-md hover:bg-zinc-900 flex items-center gap-2"
                    >
                      OS
                    </button>

                    {openMenu === "os" && (
                      <div
                        className="absolute left-0 top-full mt-1 w-56 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-20"
                        onMouseEnter={() => openWithHover("os")}
                        onMouseLeave={scheduleClose}
                      >
                        {can("os.read") && (
                          <Link href="/os" className="block px-3 py-2 hover:bg-zinc-900">
                            OSs
                          </Link>
                        )}
                        {can("os.read") && (
                          <Link href="/projetos" className="block px-3 py-2 hover:bg-zinc-900">
                            Projetos
                          </Link>
                        )}
                        {canExecuteOs && (
                          <Link href="/execucao" className="block px-3 py-2 hover:bg-zinc-900">
                            Execucao
                          </Link>
                        )}
                        {canExecuteOs && (
                          <Link href="/baixa_os" className="block px-3 py-2 hover:bg-zinc-900">
                            Baixa PC
                          </Link>
                        )}
                        {canExecuteOs && (
                          <Link href="/baixa_os_cel" className="block px-3 py-2 hover:bg-zinc-900">
                            Baixa Celular
                          </Link>
                        )}
                        {canAccessApontamentos && (
                          <Link href="/apontamentos" className="block px-3 py-2 hover:bg-zinc-900">
                            Apontamentos Horas
                          </Link>
                        )}
                      </div>
                    )}
                  </div>
                )}

                {canAccessEstoque && (
                  <div
                    className="relative"
                    onMouseEnter={() => openWithHover("estoque")}
                    onMouseLeave={scheduleClose}
                  >
                    <button
                      type="button"
                      onClick={() => toggleMenu("estoque")}
                      className="px-3 py-1 rounded-md hover:bg-zinc-900 flex items-center gap-2"
                    >
                      Estoque
                    </button>

                    {openMenu === "estoque" && (
                      <div
                        className="absolute left-0 top-full mt-1 w-52 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-20"
                        onMouseEnter={() => openWithHover("estoque")}
                        onMouseLeave={scheduleClose}
                      >
                        {can("estoque.read") && (
                          <Link href="/estoque" className="block px-3 py-2 hover:bg-zinc-900">
                            Ajuste Estoque
                          </Link>
                        )}
                        {canAccessCadastroItens && (
                          <Link href="/itens" className="block px-3 py-2 hover:bg-zinc-900">
                            Cadastro
                          </Link>
                        )}
                        {canImportXml && (
                          <Link href="/estoque/importar" className="block px-3 py-2 hover:bg-zinc-900">
                            Importar XML
                          </Link>
                        )}
                        {can("estoque.read") && (
                          <Link href="/mov" className="block px-3 py-2 hover:bg-zinc-900">
                            Movimentacoes
                          </Link>
                        )}
                      </div>
                    )}
                  </div>
                )}

                {canAccessFinanceiro && (
                  <div
                    className="relative"
                    onMouseEnter={() => openWithHover("financeiro")}
                    onMouseLeave={scheduleClose}
                  >
                    <button
                      type="button"
                      onClick={() => toggleMenu("financeiro")}
                      className="px-3 py-1 rounded-md hover:bg-zinc-900 flex items-center gap-2"
                    >
                      Financeiro
                    </button>

                    {openMenu === "financeiro" && (
                      <div
                        className="absolute left-0 top-full mt-1 w-64 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-20"
                        onMouseEnter={() => openWithHover("financeiro")}
                        onMouseLeave={scheduleClose}
                      >
                        {/* item simples */}
                        <Link href="/financeiro" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                          Dashboard
                        </Link>

                        <div className="border-t border-zinc-800 my-2" />

                        {/* item com flyout (submenu à direita) */}
                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Contas a Pagar</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <Link href="/financeiro/contas-pagar/lancamentos" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Lançamentos
                            </Link>
                            <Link href="/financeiro/contas-pagar/aprovacoes" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Aprovações
                            </Link>
                            <Link href="/financeiro/contas-pagar/pagamentos" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Pagamentos
                            </Link>
                          </div>
                        </div>

                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Contas a Receber</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <Link href="/financeiro/contas-receber/lancamentos" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Lançamentos
                            </Link>
                            <Link href="/financeiro/contas-receber/recebimentos" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Recebimentos
                            </Link>
                          </div>
                        </div>

                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Caixa &amp; Bancos</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <Link href="/financeiro/extratos" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Extratos Bancários
                            </Link>
                            <Link href="/financeiro/conciliacao" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Conciliação Bancária
                            </Link>
                            <Link href="/financeiro/transferencias" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Transferências
                            </Link>
                          </div>
                        </div>

                        <div className="border-t border-zinc-800 my-2" />

                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Cadastros</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Estrutura</div>
                            <Link href="/financeiro/cadastros/plano-contas" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Plano de Contas
                            </Link>
                            <Link href="/financeiro/cadastros/centro-custo" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Centros de Custo
                            </Link>

                            <div className="border-t border-zinc-800 my-2" />
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Bancos</div>
                            <Link href="/financeiro/cadastros/contas-bancarias" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Contas Bancárias
                            </Link>

                            <div className="border-t border-zinc-800 my-2" />
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Classificações</div>
                            <Link href="/financeiro/cadastros/motivos-compra" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Motivos / Classificação de Compra
                            </Link>
                          </div>
                        </div>

                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Relatórios</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Fluxo de Caixa</div>
                            <Link href="/financeiro/relatorios/fluxo-caixa/previsto" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Previsto
                            </Link>
                            <Link href="/financeiro/relatorios/fluxo-caixa/realizado" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Realizado
                            </Link>
                            <Link href="/financeiro/relatorios/fluxo-caixa/diario" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Diário
                            </Link>

                            <div className="border-t border-zinc-800 my-2" />
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Aging</div>
                            <Link href="/financeiro/relatorios/ap-aging" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Aging (Contas a Pagar)
                            </Link>
                            <Link href="/financeiro/relatorios/ar-aging" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Aging (Contas a Receber)
                            </Link>
                          </div>
                        </div>

                        <Link href="/financeiro/configuracoes" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                          Configurações
                        </Link>

                        <div className="border-t border-zinc-800 my-2" />

                        <div className="relative group/fin">
                          <div className="px-3 py-2 hover:bg-zinc-900 text-sm flex items-center justify-between cursor-default select-none">
                            <span>Legado</span>
                            <span className="text-zinc-500">{">"}</span>
                          </div>

                          <div className="hidden group-hover/fin:block absolute left-full top-0 ml-1 w-72 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-30">
                            <Link href="/financeiro/contas_pagar_receber" className="block px-3 py-2 hover:bg-zinc-900 text-sm">
                              Contas a pagar/Receber (antigo)
                            </Link>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {canAccessCadastros && (
                  <div
                    className="relative"
                    onMouseEnter={() => openWithHover("cadastro")}
                    onMouseLeave={scheduleClose}
                  >
                    <button
                      type="button"
                      onClick={() => toggleMenu("cadastro")}
                      className="px-3 py-1 rounded-md hover:bg-zinc-900 flex items-center gap-2"
                    >
                      Cadastros
                    </button>

                    {openMenu === "cadastro" && (
                      <div
                        className="absolute left-0 top-full mt-1 w-56 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-20"
                        onMouseEnter={() => openWithHover("cadastro")}
                        onMouseLeave={scheduleClose}
                      >
                        {canAccessContratos && (
                          <>
                            <div className="px-3 py-2 text-xs font-semibold text-zinc-400">Contratos HH</div>
                            <Link href="/cadastros/hh/tabelas" className="block px-5 py-2 hover:bg-zinc-900 text-sm">
                              Tabelas
                            </Link>
                            <Link
                              href="/cadastros/hh/servicos-cliente"
                              className="block px-5 py-2 hover:bg-zinc-900 text-sm"
                            >
                              Especialidades
                            </Link>
                            <Link
                              href="/cadastros/hh/colaboradores-cliente"
                              className="block px-5 py-2 hover:bg-zinc-900 text-sm"
                            >
                              Colaboradores - Cliente
                            </Link>
                            <div className="border-t border-zinc-800 my-2"></div>
                          </>
                        )}
                        {canAccessColaboradores && (
                          <>
                            <Link href="/colaboradores" className="block px-3 py-2 hover:bg-zinc-900">
                              Colaboradores
                            </Link>
                            <div className="border-t border-zinc-800 my-2"></div>
                          </>
                        )}
                        {canAccessClientesCad && (
                          <>
                            <Link href="/clientes" className="block px-3 py-2 hover:bg-zinc-900">
                              Clientes
                            </Link>
                            <div className="border-t border-zinc-800 my-2"></div>
                          </>
                        )}
                        {canAccessFornecedoresCad && (
                          <Link href="/estoque/fornecedores" className="block px-3 py-2 hover:bg-zinc-900">
                            Fornecedores
                          </Link>
                        )}
                      </div>
                    )}
                  </div>
                )}

                {shouldShowAdmin && (
                  <div className="relative" onMouseEnter={() => openWithHover("admin")} onMouseLeave={scheduleClose}>
                    <button
                      type="button"
                      onClick={() => toggleMenu("admin")}
                      className="px-3 py-1 rounded-md hover:bg-zinc-900 flex items-center gap-2"
                    >
                      Admin
                    </button>

                    {openMenu === "admin" && (
                      <div
                        className="absolute left-0 top-full mt-1 w-52 rounded-md border border-zinc-800 bg-zinc-950 shadow-lg py-2 z-20"
                        onMouseEnter={() => openWithHover("admin")}
                        onMouseLeave={scheduleClose}
                      >
                        <Link href="/admin/usuarios" className="block px-3 py-2 hover:bg-zinc-900">
                          Usuarios
                        </Link>
                        <Link href="/admin/empresas" className="block px-3 py-2 hover:bg-zinc-900">
                          Empresas
                        </Link>
                      </div>
                    )}
                  </div>
                )}
              </nav>
            </div>

            <div className="flex items-center gap-3">
              {te.refreshing && (
                <div className="text-[11px] text-zinc-400 whitespace-nowrap">
                  Atualizando...
                </div>
              )}

              {te.error && <div className="text-xs text-red-400 max-w-[240px]">{te.error}</div>}

              {effectiveEmpresa && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-zinc-400">Empresa:</span>
                  <span className="text-xs text-zinc-100 font-medium">
                    {effectiveEmpresa.nome_fantasia ?? effectiveEmpresa.razao_social ?? "Empresa"}
                  </span>
                </div>
              )}
              {!effectiveEmpresa && te.sessionUserId && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-zinc-400">Empresa:</span>
                  <span className="text-xs text-zinc-100 font-medium opacity-70">
                    Carregando...
                  </span>
                </div>
              )}

              <div className="flex flex-col items-end gap-1">
                {te.sessionEmail && (
                  <div className="text-xs text-zinc-300 select-none whitespace-nowrap">
                    <div>{te.sessionEmail}</div>
                  </div>
                )}
                <AdminDebugPanel
                  providerBuildId={te.providerBuildId}
                  sessionUserId={te.sessionUserId}
                  email={te.sessionEmail}
                  tenantId={te.tenantId}
                  empresaId={te.empresaId}
                  empresas={te.empresas}
                  isAdminTenant={isTenantAdmin}
                  adminLoading={adminLoading}
                  capabilities={te.capabilities}
                  lastLoadPermissions={te.lastLoadPermissions}
                  lastLoadPermissionsRaw={te.lastLoadPermissionsRaw}
                  lastLoadSource={te.lastLoadSource}
                  lastLoadCount={te.lastLoadCount}
                  lastLoadError={te.lastLoadError}
                  can={can}
                  canAdminManageUsers={canAccessAdmin}
                  shouldShowAdmin={shouldShowAdmin}
                  reason={adminReason}
                  onRefreshCapabilities={te.refreshCapabilities}
                />
              </div>

              <button
                type="button"
                onClick={logout}
                className="px-3 py-1.5 rounded-md bg-zinc-100 text-zinc-900 hover:bg-white text-sm font-medium"
              >
                Sair
              </button>
            </div>
          </div>
        </header>
      )}

      <main
        className={
          hideHeader
            ? "w-full px-6 py-6"
            : isFullWidth
              ? "w-full px-4 md:px-6 py-6"
              : "mx-auto max-w-6xl px-4 py-6"
        }
      >
        {children}
      </main>
    </div>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import { getSupabaseBrowser } from "@/lib/auth/supabase";
import { useTenantEmpresa, useIsAdminTenant } from "@/lib/auth/hooks";
import type { Capabilities, CapabilityKey } from "@/lib/auth/capabilities";
import AdminDebugPanel from "./AdminDebugPanel";
import SessionKeepAlive from "@/components/auth/SessionKeepAlive";

const isDev = process.env.NODE_ENV !== "production";
const logError = (...args: unknown[]) => {
  if (isDev) console.warn(...args);
};

export default function AppShellClient({ children }: { children: React.ReactNode }) {
  const te = useTenantEmpresa();

  const router = useRouter();
  const pathname = usePathname();

  const isLoginPage = pathname === "/login";
  const isResetPasswordPage =
    pathname === "/reset-password" ||
    pathname === "/auth/reset-password" ||
    pathname === "/reset-password/" ||
    pathname === "/auth/reset-password/";
  const isPublic = isLoginPage || isResetPasswordPage;
  const isFullWidth =
    pathname === "/itens" ||
    pathname === "/itens/imprimir" ||
    pathname === "/financeiro/contas-pagar/aprovacoes" ||
    pathname === "/financeiro/impostos" ||
    pathname === "/financeiro/contas_pagar_receber" ||
    pathname?.startsWith("/financeiro/contas_pagar_receber/");

  const { isAdmin: isAdminTenant, loading: adminLoading } = useIsAdminTenant();
  const lastKnownCapsRef = useRef<Capabilities | null>(null);
  const didAutoSelectEmpresaRef = useRef(false);
  const lastUserIdRef = useRef<string | null>(null);

  const empresaId = te.empresaId;
  const empresas = te.empresas;

  const effectiveEmpresa = useMemo(() => {
    if (empresaId) return empresas.find((e) => e.id === empresaId) ?? null;
    if (empresas.length === 1) return empresas[0];
    return null;
  }, [empresaId, empresas]);

  const empresaRole = useMemo(() => {
    const role = effectiveEmpresa?.papel;
    return typeof role === "string" ? role.trim().toUpperCase() : "";
  }, [effectiveEmpresa?.papel]);
  const isPainelTv = empresaRole === "PAINEL_TV";

  const hideHeader =
    isPainelTv ||
    pathname === "/itens/imprimir" ||
    pathname === "/estoque/importar/imprimir" ||
    pathname === "/painel-tv" ||
    pathname?.startsWith("/projetos") ||
    pathname?.startsWith("/execucao");

  useEffect(() => {
    if (te.capabilities) lastKnownCapsRef.current = te.capabilities;
  }, [te.capabilities]);

  useEffect(() => {
    const userId = te.sessionUserId;
    if (userId === undefined) return;

    if (userId === null) {
      lastUserIdRef.current = null;
      lastKnownCapsRef.current = null;
      didAutoSelectEmpresaRef.current = false;
      return;
    }

    if (userId !== lastUserIdRef.current) {
      lastUserIdRef.current = userId;
      lastKnownCapsRef.current = null;
      didAutoSelectEmpresaRef.current = false;
    }
  }, [te.sessionUserId]);

  useEffect(() => {
    if (didAutoSelectEmpresaRef.current) return;
    if (!te.sessionUserId) return;
    if (!empresaId && empresas.length === 1) {
      didAutoSelectEmpresaRef.current = true;
      void te.setEmpresaId(empresas[0].id);
    }
  }, [empresaId, empresas, te.sessionUserId, te.setEmpresaId]);

  useEffect(() => {
    const sessionUserId = te.sessionUserId;
    if (sessionUserId === undefined) return;
    const isAuthed = Boolean(sessionUserId);
    // Only redirect authed users away from the login page.
    // Password reset links often establish a session; keep user on reset screen.
    if (isAuthed && isLoginPage) router.replace("/");
  }, [isLoginPage, isPublic, router, te.sessionUserId]);

  useEffect(() => {
    if (te.sessionUserId === undefined) return;
    if (!te.sessionUserId) return;
    if (!isPainelTv) return;
    if (!effectiveEmpresa) return;

    const allowed =
      pathname === "/painel" ||
      pathname === "/painel-tv" ||
      pathname.startsWith("/painel-tv/") ||
      pathname === "/projetos" ||
      pathname.startsWith("/projetos/") ||
      pathname === "/execucao" ||
      pathname.startsWith("/execucao/");

    if (!allowed) router.replace("/painel-tv");
  }, [effectiveEmpresa, isPainelTv, pathname, router, te.sessionUserId]);

  const [openMenu, setOpenMenu] = useState<
    "os" | "estoque" | "imobilizado" | "financeiro" | "faturamento" | "cadastro" | "admin" | null
  >(null);
