        setSolicitanteUsuarioId((prev) => (prev && !next.some((u) => u.id === prev) ? "" : prev));
      } catch (e: unknown) {
        if (!active) return;
        setUsuariosSolicitantes([]);
        setUsuariosSolicitantesError(getErrorMessage(e, "Erro ao carregar usuarios."));
