                      className="w-full bg-zinc-950 border border-zinc-800 rounded-md px-3 py-2 text-sm text-zinc-100"
                    />
                    <div className="text-xs text-zinc-500 mt-1">Dica: ele copia o valor do mês anterior por padrão.</div>
                  </div>
