): Promise<{ tenantIds: string[]; empresaIds: string[] }> {
  try {
    const { data, error } = await supabase
      .from("empresa_memberships")
      .select("tenant_id,empresa_id")
      .eq("user_id", userId)
      .eq("status", "active");
    if (error) return { tenantIds: [], empresaIds: [] };

