  let deleteError: unknown | null = null;
  try {
    await supabase
      .from("apontamentos_horas")
      .delete()
      .match({
        tenant_id: tenantId,
        os_id: osId,
        colaborador_id: colaboradorId,
        data: dataISO,
        gerado_por_hh: true,
      });
  } catch (e: unknown) {
    if (isMissingColumnError(e, "gerado_por_hh")) {
